_PUBLIC_ bool islower_m(codepoint_t val)
{
	return (toupper_m(val) != val);
}

_PUBLIC_ codepoint_t tolower_m(codepoint_t val)
{
	if (val < 128) {
		return tolower(val);
	}
	if (val >= ARRAY_SIZE(lowcase_table)) {
		return val;
	}
	return lowcase_table[val];
}

