static void  Interp( Int  p1, Int  p2,
                     Int  ref1, Int  ref2,
                     struct LOC_Ins_IUP*  LINK )
{
  Long        i;
  TT_F26Dot6  x, x1, x2, d1, d2;

  if ( p1 > p2 )
    return;

  x1 = LINK->orgs[ref1];
  d1 = LINK->curs[ref1] - LINK->orgs[ref1];
  x2 = LINK->orgs[ref2];
  d2 = LINK->curs[ref2] - LINK->orgs[ref2];

  if ( x1 == x2 )
  {
    for ( i = p1; i <= p2; i++ )
    {
      x = LINK->orgs[i];

      if ( x <= x1 )
        x += d1;
      else
        x += d2;

      LINK->curs[i] = x;
    }
    return;
  }

  if ( x1 < x2 )
  {
    for ( i = p1; i <= p2; i++ )
    {
      x = LINK->orgs[i];

      if ( x <= x1 )
        x += d1;
      else
      {
        if ( x >= x2 )
          x += d2;
        else
          x = LINK->curs[ref1] +
                MulDiv_Round( x - x1,
                              LINK->curs[ref2] - LINK->curs[ref1],
                              x2 - x1 );
      }
      LINK->curs[i] = x;
    }
    return;
  }

  /* x2 < x1 */

  for ( i = p1; i <= p2; i++ )
  {
    x = LINK->orgs[i];
    if ( x <= x2 )
      x += d2;
    else
    {
      if ( x >= x1 )
        x += d1;
      else
        x = LINK->curs[ref1] +
              MulDiv_Round( x - x1,
                            LINK->curs[ref2] - LINK->curs[ref1],
                            x2 - x1 );
    }
    LINK->curs[i] = x;
  }
}

static Bool  Normalize( EXEC_OPS TT_F26Dot6      Vx,
                                 TT_F26Dot6      Vy,
                                 TT_UnitVector*  R )
{
  TT_F26Dot6  W;
  Bool        S1, S2;

  if ( ABS( Vx ) < 0x10000L && ABS( Vy ) < 0x10000L )
  {
    Vx *= 0x100;
    Vy *= 0x100;

    W = Norm( Vx, Vy );

    if ( W == 0 )
    {
      /* XXX : Undocumented. It seems that it's possible to try  */
      /*       to normalize the vector (0,0). Return immediately */
      return SUCCESS;
    }

    R->x = (TT_F2Dot14)MulDiv_Round( Vx, 0x4000L, W );
    R->y = (TT_F2Dot14)MulDiv_Round( Vy, 0x4000L, W );

    return SUCCESS;
  }

  W = Norm( Vx, Vy );

  if ( W <= 0 )
  {
    CUR.error = TT_Err_Divide_By_Zero;
    return FAILURE;
  }

  Vx = MulDiv_Round( Vx, 0x4000L, W );
  Vy = MulDiv_Round( Vy, 0x4000L, W );

  W = Vx * Vx + Vy * Vy;

  /* Now, we want that Sqrt( W ) = 0x4000 */
  /* Or 0x10000000 <= W < 0x10004000      */

  if ( Vx < 0 )
  {
    Vx = -Vx;
    S1 = TRUE;
  }
  else
    S1 = FALSE;

  if ( Vy < 0 )
  {
    Vy = -Vy;
    S2 = TRUE;
  }
  else
    S2 = FALSE;

  while ( W < 0x10000000L )
  {
    /* We need to increase W, by a minimal amount */
    if ( Vx < Vy )
      Vx++;
    else
      Vy++;

    W = Vx * Vx + Vy * Vy;
  }

  while ( W >= 0x10004000L )
  {
    /* We need to decrease W, by a minimal amount */
    if ( Vx < Vy )
      Vx--;
    else
      Vy--;

    W = Vx * Vx + Vy * Vy;
  }

  /* Note that in various cases, we can only  */
  /* compute a Sqrt(W) of 0x3FFF, eg. Vx = Vy */

  if ( S1 )
    Vx = -Vx;

  if ( S2 )
    Vy = -Vy;

  R->x = (TT_F2Dot14)Vx;   /* Type conversion */
  R->y = (TT_F2Dot14)Vy;   /* Type conversion */

  return SUCCESS;
}

