tt_cmap2_validate( FT_Byte*      table,
                   FT_Validator  valid )
{
  FT_Byte*  p;
  FT_UInt   length;

  FT_UInt   n, max_subs;
  FT_Byte*  keys;        /* keys table     */
  FT_Byte*  subs;        /* sub-headers    */
  FT_Byte*  glyph_ids;   /* glyph ID array */


  if ( table + 2 + 2 > valid->limit )
    FT_INVALID_TOO_SHORT;

  p      = table + 2;           /* skip format */
  length = TT_NEXT_USHORT( p );

  if ( table + length > valid->limit || length < 6 + 512 )
    FT_INVALID_TOO_SHORT;

  keys = table + 6;

  /* parse keys to compute sub-headers count */
  p        = keys;
  max_subs = 0;
  for ( n = 0; n < 256; n++ )
  {
    FT_UInt  idx = TT_NEXT_USHORT( p );


    /* value must be multiple of 8 */
    if ( valid->level >= FT_VALIDATE_PARANOID && ( idx & 7 ) != 0 )
      FT_INVALID_DATA;

    idx >>= 3;

    if ( idx > max_subs )
      max_subs = idx;
  }

  FT_ASSERT( p == table + 518 );

  subs      = p;
  glyph_ids = subs + (max_subs + 1) * 8;
  if ( glyph_ids > valid->limit )
    FT_INVALID_TOO_SHORT;

  /* parse sub-headers */
  for ( n = 0; n <= max_subs; n++ )
  {
    FT_UInt  first_code, code_count, offset;
    FT_Int   delta;


    first_code = TT_NEXT_USHORT( p );
    code_count = TT_NEXT_USHORT( p );
    delta      = TT_NEXT_SHORT( p );
    offset     = TT_NEXT_USHORT( p );

    /* many Dynalab fonts have empty sub-headers */
    if ( code_count == 0 )
      continue;

    /* check range within 0..255 */
    if ( valid->level >= FT_VALIDATE_PARANOID )
    {
      if ( first_code >= 256 || first_code + code_count > 256 )
        FT_INVALID_DATA;
    }

    /* check offset */
    if ( offset != 0 )
    {
      FT_Byte*  ids;


      ids = p - 2 + offset;
      if ( ids < glyph_ids || ids + code_count*2 > table + length )
        FT_INVALID_OFFSET;

      /* check glyph IDs */
      if ( valid->level >= FT_VALIDATE_TIGHT )
      {
        FT_Byte*  limit = p + code_count * 2;
        FT_UInt   idx;


        for ( ; p < limit; )
        {
          idx = TT_NEXT_USHORT( p );
          if ( idx != 0 )
          {
            idx = ( idx + delta ) & 0xFFFFU;
            if ( idx >= TT_VALID_GLYPH_COUNT( valid ) )
              FT_INVALID_GLYPH_ID;
          }
        }
      }
    }
  }

  return FT_Err_Ok;
}

tt_cmap4_validate( FT_Byte*      table,
                   FT_Validator  valid )
{
  FT_Byte*  p;
  FT_UInt   length;

  FT_Byte   *ends, *starts, *offsets, *deltas, *glyph_ids;
  FT_UInt   num_segs;
  FT_Error  error = FT_Err_Ok;


  if ( table + 2 + 2 > valid->limit )
    FT_INVALID_TOO_SHORT;

  p      = table + 2;           /* skip format */
  length = TT_NEXT_USHORT( p );

  if ( length < 16 )
    FT_INVALID_TOO_SHORT;

  /* in certain fonts, the `length' field is invalid and goes */
  /* out of bound.  We try to correct this here...            */
  if ( table + length > valid->limit )
  {
    if ( valid->level >= FT_VALIDATE_TIGHT )
      FT_INVALID_TOO_SHORT;

    length = (FT_UInt)( valid->limit - table );
  }

  p        = table + 6;
  num_segs = TT_NEXT_USHORT( p );   /* read segCountX2 */

  if ( valid->level >= FT_VALIDATE_PARANOID )
  {
    /* check that we have an even value here */
    if ( num_segs & 1 )
      FT_INVALID_DATA;
  }

  num_segs /= 2;

  if ( length < 16 + num_segs * 2 * 4 )
    FT_INVALID_TOO_SHORT;

  /* check the search parameters - even though we never use them */
  /*                                                             */
  if ( valid->level >= FT_VALIDATE_PARANOID )
  {
    /* check the values of `searchRange', `entrySelector', `rangeShift' */
    FT_UInt  search_range   = TT_NEXT_USHORT( p );
    FT_UInt  entry_selector = TT_NEXT_USHORT( p );
    FT_UInt  range_shift    = TT_NEXT_USHORT( p );


    if ( ( search_range | range_shift ) & 1 )  /* must be even values */
      FT_INVALID_DATA;

    search_range /= 2;
    range_shift  /= 2;

    /* `search range' is the greatest power of 2 that is <= num_segs */

    if ( search_range                > num_segs                 ||
         search_range * 2            < num_segs                 ||
         search_range + range_shift != num_segs                 ||
         search_range               != ( 1U << entry_selector ) )
      FT_INVALID_DATA;
  }

  ends      = table   + 14;
  starts    = table   + 16 + num_segs * 2;
  deltas    = starts  + num_segs * 2;
  offsets   = deltas  + num_segs * 2;
  glyph_ids = offsets + num_segs * 2;

  /* check last segment; its end count value must be 0xFFFF */
  if ( valid->level >= FT_VALIDATE_PARANOID )
  {
    p = ends + ( num_segs - 1 ) * 2;
    if ( TT_PEEK_USHORT( p ) != 0xFFFFU )
      FT_INVALID_DATA;
  }

  {
    FT_UInt   start, end, offset, n;
    FT_UInt   last_start = 0, last_end = 0;
    FT_Int    delta;
    FT_Byte*  p_start   = starts;
    FT_Byte*  p_end     = ends;
    FT_Byte*  p_delta   = deltas;
    FT_Byte*  p_offset  = offsets;


    for ( n = 0; n < num_segs; n++ )
    {
      p      = p_offset;
      start  = TT_NEXT_USHORT( p_start );
      end    = TT_NEXT_USHORT( p_end );
      delta  = TT_NEXT_SHORT( p_delta );
      offset = TT_NEXT_USHORT( p_offset );

      if ( start > end )
        FT_INVALID_DATA;

      /* this test should be performed at default validation level; */
      /* unfortunately, some popular Asian fonts have overlapping   */
      /* ranges in their charmaps                                   */
      /*                                                            */
      if ( start <= last_end && n > 0 )
      {
        if ( valid->level >= FT_VALIDATE_TIGHT )
          FT_INVALID_DATA;
        else
        {
          /* allow overlapping segments, provided their start points */
          /* and end points, respectively, are in ascending order    */
          /*                                                         */
          if ( last_start > start || last_end > end )
            error |= TT_CMAP_FLAG_UNSORTED;
          else
            error |= TT_CMAP_FLAG_OVERLAPPING;
        }
      }

      if ( offset && offset != 0xFFFFU )
      {
        p += offset;  /* start of glyph ID array */

        /* check that we point within the glyph IDs table only */
        if ( valid->level >= FT_VALIDATE_TIGHT )
        {
          if ( p < glyph_ids                                ||
               p + ( end - start + 1 ) * 2 > table + length )
            FT_INVALID_DATA;
        }
        /* Some fonts handle the last segment incorrectly.  In */
        /* theory, 0xFFFF might point to an ordinary glyph --  */
        /* a cmap 4 is versatile and could be used for any     */
        /* encoding, not only Unicode.  However, reality shows */
        /* that far too many fonts are sloppy and incorrectly  */
        /* set all fields but `start' and `end' for the last   */
        /* segment if it contains only a single character.     */
        /*                                                     */
        /* We thus omit the test here, delaying it to the      */
        /* routines which actually access the cmap.            */
        else if ( n != num_segs - 1                       ||
                  !( start == 0xFFFFU && end == 0xFFFFU ) )
        {
          if ( p < glyph_ids                              ||
               p + ( end - start + 1 ) * 2 > valid->limit )
            FT_INVALID_DATA;
        }

        /* check glyph indices within the segment range */
        if ( valid->level >= FT_VALIDATE_TIGHT )
        {
          FT_UInt  i, idx;


          for ( i = start; i < end; i++ )
          {
            idx = FT_NEXT_USHORT( p );
            if ( idx != 0 )
            {
              idx = (FT_UInt)( idx + delta ) & 0xFFFFU;

              if ( idx >= TT_VALID_GLYPH_COUNT( valid ) )
                FT_INVALID_GLYPH_ID;
            }
          }
        }
      }
      else if ( offset == 0xFFFFU )
      {
        /* some fonts (erroneously?) use a range offset of 0xFFFF */
        /* to mean missing glyph in cmap table                    */
        /*                                                        */
        if ( valid->level >= FT_VALIDATE_PARANOID    ||
             n != num_segs - 1                       ||
             !( start == 0xFFFFU && end == 0xFFFFU ) )
          FT_INVALID_DATA;
      }

      last_start = start;
      last_end   = end;
    }
  }

  return error;
}

tt_cmap6_get_info( TT_CMap       cmap,
                   TT_CMapInfo  *cmap_info )
{
  FT_Byte*  p = cmap->data + 4;


  cmap_info->format   = 6;
  cmap_info->language = (FT_ULong)TT_PEEK_USHORT( p );

  return FT_Err_Ok;
}

tt_face_get_name( TT_Face      face,
                  FT_UShort    nameid,
                  FT_String**  name )
{
  FT_Memory         memory = face->root.memory;
  FT_Error          error  = FT_Err_Ok;
  FT_String*        result = NULL;
  FT_UShort         n;
  TT_NameEntryRec*  rec;
  FT_Int            found_apple         = -1;
  FT_Int            found_apple_roman   = -1;
  FT_Int            found_apple_english = -1;
  FT_Int            found_win           = -1;
  FT_Int            found_unicode       = -1;

  FT_Bool           is_english = 0;

  TT_NameEntry_ConvertFunc  convert;


  FT_ASSERT( name );

  rec = face->name_table.names;
  for ( n = 0; n < face->num_names; n++, rec++ )
  {
    /* According to the OpenType 1.3 specification, only Microsoft or  */
    /* Apple platform IDs might be used in the `name' table.  The      */
    /* `Unicode' platform is reserved for the `cmap' table, and the    */
    /* `ISO' one is deprecated.                                        */
    /*                                                                 */
    /* However, the Apple TrueType specification doesn't say the same  */
    /* thing and goes to suggest that all Unicode `name' table entries */
    /* should be coded in UTF-16 (in big-endian format I suppose).     */
    /*                                                                 */
    if ( rec->nameID == nameid && rec->stringLength > 0 )
    {
      switch ( rec->platformID )
      {
      case TT_PLATFORM_APPLE_UNICODE:
      case TT_PLATFORM_ISO:
        /* there is `languageID' to check there.  We should use this */
        /* field only as a last solution when nothing else is        */
        /* available.                                                */
        /*                                                           */
        found_unicode = n;
        break;

      case TT_PLATFORM_MACINTOSH:
        /* This is a bit special because some fonts will use either    */
        /* an English language id, or a Roman encoding id, to indicate */
        /* the English version of its font name.                       */
        /*                                                             */
        if ( rec->languageID == TT_MAC_LANGID_ENGLISH )
          found_apple_english = n;
        else if ( rec->encodingID == TT_MAC_ID_ROMAN )
          found_apple_roman = n;
        break;

      case TT_PLATFORM_MICROSOFT:
        /* we only take a non-English name when there is nothing */
        /* else available in the font                            */
        /*                                                       */
        if ( found_win == -1 || ( rec->languageID & 0x3FF ) == 0x009 )
        {
          switch ( rec->encodingID )
          {
          case TT_MS_ID_SYMBOL_CS:
          case TT_MS_ID_UNICODE_CS:
          case TT_MS_ID_UCS_4:
            is_english = FT_BOOL( ( rec->languageID & 0x3FF ) == 0x009 );
            found_win  = n;
            break;

          default:
            ;
          }
        }
        break;

      default:
        ;
      }
    }
  }

  found_apple = found_apple_roman;
  if ( found_apple_english >= 0 )
    found_apple = found_apple_english;

  /* some fonts contain invalid Unicode or Macintosh formatted entries; */
  /* we will thus favor names encoded in Windows formats if available   */
  /* (provided it is an English name)                                   */
  /*                                                                    */
  convert = NULL;
  if ( found_win >= 0 && !( found_apple >= 0 && !is_english ) )
  {
    rec = face->name_table.names + found_win;
    switch ( rec->encodingID )
    {
      /* all Unicode strings are encoded using UTF-16BE */
    case TT_MS_ID_UNICODE_CS:
    case TT_MS_ID_SYMBOL_CS:
      convert = tt_name_entry_ascii_from_utf16;
      break;

    case TT_MS_ID_UCS_4:
      /* Apparently, if this value is found in a name table entry, it is */
      /* documented as `full Unicode repertoire'.  Experience with the   */
      /* MsGothic font shipped with Windows Vista shows that this really */
      /* means UTF-16 encoded names (UCS-4 values are only used within   */
      /* charmaps).                                                      */
      convert = tt_name_entry_ascii_from_utf16;
      break;

    default:
      ;
    }
  }
  else if ( found_apple >= 0 )
  {
    rec     = face->name_table.names + found_apple;
    convert = tt_name_entry_ascii_from_other;
  }
  else if ( found_unicode >= 0 )
  {
    rec     = face->name_table.names + found_unicode;
    convert = tt_name_entry_ascii_from_utf16;
  }

  if ( rec && convert )
  {
    if ( rec->string == NULL )
    {
      FT_Stream  stream = face->name_table.stream;


      if ( FT_QNEW_ARRAY ( rec->string, rec->stringLength ) ||
           FT_STREAM_SEEK( rec->stringOffset )              ||
           FT_STREAM_READ( rec->string, rec->stringLength ) )
      {
        FT_FREE( rec->string );
        rec->stringLength = 0;
        result            = NULL;
        goto Exit;
      }
    }

    result = convert( rec, memory );
  }

Exit:
  *name = result;
  return error;
}

tt_sbit_decoder_load_bit_aligned( TT_SBitDecoder  decoder,
                                  FT_Byte*        p,
                                  FT_Byte*        limit,
                                  FT_Int          x_pos,
                                  FT_Int          y_pos )
{
  FT_Error    error = FT_Err_Ok;
  FT_Byte*    line;
  FT_Int      bit_height, bit_width, pitch, width, height, line_bits, h, nbits;
  FT_Bitmap*  bitmap;
  FT_UShort   rval;


  /* check that we can write the glyph into the bitmap */
  bitmap     = decoder->bitmap;
  bit_width  = bitmap->width;
  bit_height = bitmap->rows;
  pitch      = bitmap->pitch;
  line       = bitmap->buffer;

  width  = decoder->metrics->width;
  height = decoder->metrics->height;

  line_bits = width * decoder->bit_depth;

  if ( x_pos < 0 || x_pos + width  > bit_width  ||
       y_pos < 0 || y_pos + height > bit_height )
  {
    FT_TRACE1(( "tt_sbit_decoder_load_bit_aligned:"
                " invalid bitmap dimensions\n" ));
    error = FT_THROW( Invalid_File_Format );
    goto Exit;
  }

  if ( p + ( ( line_bits * height + 7 ) >> 3 ) > limit )
  {
    FT_TRACE1(( "tt_sbit_decoder_load_bit_aligned: broken bitmap\n" ));
    error = FT_THROW( Invalid_File_Format );
    goto Exit;
  }

  /* now do the blit */

  /* adjust `line' to point to the first byte of the bitmap */
  line  += y_pos * pitch + ( x_pos >> 3 );
  x_pos &= 7;

  /* the higher byte of `rval' is used as a buffer */
  rval  = 0;
  nbits = 0;

  for ( h = height; h > 0; h--, line += pitch )
  {
    FT_Byte*  pwrite = line;
    FT_Int    w      = line_bits;


    /* handle initial byte (in target bitmap) specially if necessary */
    if ( x_pos )
    {
      w = ( line_bits < 8 - x_pos ) ? line_bits : 8 - x_pos;

      if ( h == height )
      {
        rval  = *p++;
        nbits = x_pos;
      }
      else if ( nbits < w )
      {
        if ( p < limit )
          rval |= *p++;
        nbits += 8 - w;
      }
      else
      {
        rval  >>= 8;
        nbits  -= w;
      }

      *pwrite++ |= ( ( rval >> nbits ) & 0xFF ) &
                   ( ~( 0xFF << w ) << ( 8 - w - x_pos ) );
      rval     <<= 8;

      w = line_bits - w;
    }

    /* handle medial bytes */
    for ( ; w >= 8; w -= 8 )
    {
      rval      |= *p++;
      *pwrite++ |= ( rval >> nbits ) & 0xFF;

      rval <<= 8;
    }

    /* handle final byte if necessary */
    if ( w > 0 )
    {
      if ( nbits < w )
      {
        if ( p < limit )
          rval |= *p++;
        *pwrite |= ( ( rval >> nbits ) & 0xFF ) & ( 0xFF00U >> w );
        nbits   += 8 - w;

        rval <<= 8;
      }
      else
      {
        *pwrite |= ( ( rval >> nbits ) & 0xFF ) & ( 0xFF00U >> w );
        nbits   -= w;
      }
    }
  }

Exit:
  if ( !error )
    FT_TRACE3(( "tt_sbit_decoder_load_bit_aligned: loaded\n" ));
  return error;
}

Bezier_Up( RAS_ARGS Int        degree,
                    TSplitter  splitter,
                    Long       miny,
                    Long       maxy )
{
  Long   y1, y2, e, e2, e0;
  Short  f1;

  TPoint*  arc;
  TPoint*  start_arc;

  PLong top;


  arc = ras.arc;
  y1  = arc[degree].y;
  y2  = arc[0].y;
  top = ras.top;

  if ( y2 < miny || y1 > maxy )
    goto Fin;

  e2 = FLOOR( y2 );

  if ( e2 > maxy )
    e2 = maxy;

  e0 = miny;

  if ( y1 < miny )
    e = miny;
  else
  {
    e  = CEILING( y1 );
    f1 = (Short)( FRAC( y1 ) );
    e0 = e;

    if ( f1 == 0 )
    {
      if ( ras.joint )
      {
        top--;
        ras.joint = FALSE;
      }

      *top++ = arc[degree].x;

      e += ras.precision;
    }
  }

  if ( ras.fresh )
  {
    ras.cProfile->start = TRUNC( e0 );
    ras.fresh = FALSE;
  }

  if ( e2 < e )
    goto Fin;

  if ( ( top + TRUNC( e2 - e ) + 1 ) >= ras.maxBuff )
  {
    ras.top   = top;
    ras.error = FT_THROW( Overflow );
    return FAILURE;
  }

  start_arc = arc;

  while ( arc >= start_arc && e <= e2 )
  {
    ras.joint = FALSE;

    y2 = arc[0].y;

    if ( y2 > e )
    {
      y1 = arc[degree].y;
      if ( y2 - y1 >= ras.precision_step )
      {
        splitter( arc );
        arc += degree;
      }
      else
      {
        *top++ = arc[degree].x + FMulDiv( arc[0].x - arc[degree].x,
                                          e - y1, y2 - y1 );
        arc -= degree;
        e   += ras.precision;
      }
    }
    else
    {
      if ( y2 == e )
      {
        ras.joint  = TRUE;
        *top++     = arc[0].x;

        e += ras.precision;
      }
      arc -= degree;
    }
  }

Fin:
  ras.top  = top;
  ras.arc -= degree;
  return SUCCESS;
}

Init_Linked( TProfileList*  l )
{
  *l = NULL;
}

Vertical_Sweep_Drop( RAS_ARGS Short       y,
                              FT_F26Dot6  x1,
                              FT_F26Dot6  x2,
                              PProfile    left,
                              PProfile    right )
{
  Long   e1, e2, pxl;
  Short  c1, f1;


  /* Drop-out control */

  /*   e2            x2                    x1           e1   */
  /*                                                         */
  /*                 ^                     |                 */
  /*                 |                     |                 */
  /*   +-------------+---------------------+------------+    */
  /*                 |                     |                 */
  /*                 |                     v                 */
  /*                                                         */
  /* pixel         contour              contour       pixel  */
  /* center                                           center */

  /* drop-out mode    scan conversion rules (as defined in OpenType) */
  /* --------------------------------------------------------------- */
  /*  0                1, 2, 3                                       */
  /*  1                1, 2, 4                                       */
  /*  2                1, 2                                          */
  /*  3                same as mode 2                                */
  /*  4                1, 2, 5                                       */
  /*  5                1, 2, 6                                       */
  /*  6, 7             same as mode 2                                */

  e1  = CEILING( x1 );
  e2  = FLOOR  ( x2 );
  pxl = e1;

  if ( e1 > e2 )
  {
    Int  dropOutControl = left->flags & 7;


    if ( e1 == e2 + ras.precision )
    {
      switch ( dropOutControl )
      {
      case 0: /* simple drop-outs including stubs */
        pxl = e2;
        break;

      case 4: /* smart drop-outs including stubs */
        pxl = FLOOR( ( x1 + x2 - 1 ) / 2 + ras.precision_half );
        break;

      case 1: /* simple drop-outs excluding stubs */
      case 5: /* smart drop-outs excluding stubs  */

        /* Drop-out Control Rules #4 and #6 */

        /* The specification neither provides an exact definition */
        /* of a `stub' nor gives exact rules to exclude them.     */
        /*                                                        */
        /* Here the constraints we use to recognize a stub.       */
        /*                                                        */
        /*  upper stub:                                           */
        /*                                                        */
        /*   - P_Left and P_Right are in the same contour         */
        /*   - P_Right is the successor of P_Left in that contour */
        /*   - y is the top of P_Left and P_Right                 */
        /*                                                        */
        /*  lower stub:                                           */
        /*                                                        */
        /*   - P_Left and P_Right are in the same contour         */
        /*   - P_Left is the successor of P_Right in that contour */
        /*   - y is the bottom of P_Left                          */
        /*                                                        */
        /* We draw a stub if the following constraints are met.   */
        /*                                                        */
        /*   - for an upper or lower stub, there is top or bottom */
        /*     overshoot, respectively                            */
        /*   - the covered interval is greater or equal to a half */
        /*     pixel                                              */

        /* upper stub test */
        if ( left->next == right                &&
             left->height <= 0                  &&
             !( left->flags & Overshoot_Top   &&
                x2 - x1 >= ras.precision_half ) )
          return;

        /* lower stub test */
        if ( right->next == left                 &&
             left->start == y                    &&
             !( left->flags & Overshoot_Bottom &&
                x2 - x1 >= ras.precision_half  ) )
          return;

        if ( dropOutControl == 1 )
          pxl = e2;
        else
          pxl = FLOOR( ( x1 + x2 - 1 ) / 2 + ras.precision_half );
        break;

      default: /* modes 2, 3, 6, 7 */
        return;  /* no drop-out control */
      }

      /* undocumented but confirmed: If the drop-out would result in a  */
      /* pixel outside of the bounding box, use the pixel inside of the */
      /* bounding box instead                                           */
      if ( pxl < 0 )
        pxl = e1;
      else if ( TRUNC( pxl ) >= ras.bWidth )
        pxl = e2;

      /* check that the other pixel isn't set */
      e1 = pxl == e1 ? e2 : e1;

      e1 = TRUNC( e1 );

      c1 = (Short)( e1 >> 3 );
      f1 = (Short)( e1 &  7 );

      if ( e1 >= 0 && e1 < ras.bWidth                      &&
           ras.bTarget[ras.traceOfs + c1] & ( 0x80 >> f1 ) )
        return;
    }
    else
      return;
  }

  e1 = TRUNC( pxl );

  if ( e1 >= 0 && e1 < ras.bWidth )
  {
    c1 = (Short)( e1 >> 3 );
    f1 = (Short)( e1 & 7 );

    if ( ras.gray_min_x > c1 )
      ras.gray_min_x = c1;
    if ( ras.gray_max_x < c1 )
      ras.gray_max_x = c1;

    ras.bTarget[ras.traceOfs + c1] |= (char)( 0x80 >> f1 );
  }
}

t42_parse_font_matrix( T42_Face    face,
                       T42_Loader  loader )
{
  T42_Parser  parser = &loader->parser;
  FT_Matrix*  matrix = &face->type1.font_matrix;
  FT_Vector*  offset = &face->type1.font_offset;
  FT_Face     root   = (FT_Face)&face->root;
  FT_Fixed    temp[6];
  FT_Fixed    temp_scale;
  FT_Int      result;


  result = T1_ToFixedArray( parser, 6, temp, 3 );

  if ( result < 6 )
  {
    parser->root.error = FT_THROW( Invalid_File_Format );
    return;
  }

  temp_scale = FT_ABS( temp[3] );

  if ( temp_scale == 0 )
  {
    FT_ERROR(( "t1_parse_font_matrix: invalid font matrix\n" ));
    parser->root.error = FT_THROW( Invalid_File_Format );
    return;
  }

  /* Set Units per EM based on FontMatrix values.  We set the value to */
  /* 1000 / temp_scale, because temp_scale was already multiplied by   */
  /* 1000 (in t1_tofixed, from psobjs.c).                              */

  root->units_per_EM = (FT_UShort)FT_DivFix( 1000, temp_scale );

  /* we need to scale the values by 1.0/temp_scale */
  if ( temp_scale != 0x10000L )
  {
    temp[0] = FT_DivFix( temp[0], temp_scale );
    temp[1] = FT_DivFix( temp[1], temp_scale );
    temp[2] = FT_DivFix( temp[2], temp_scale );
    temp[4] = FT_DivFix( temp[4], temp_scale );
    temp[5] = FT_DivFix( temp[5], temp_scale );
    temp[3] = temp[3] < 0 ? -0x10000L : 0x10000L;
  }

  matrix->xx = temp[0];
  matrix->yx = temp[1];
  matrix->xy = temp[2];
  matrix->yy = temp[3];

  /* note that the offsets must be expressed in integer font units */
  offset->x = temp[4] >> 16;
  offset->y = temp[5] >> 16;
}

t42_parse_sfnts( T42_Face    face,
                 T42_Loader  loader )
{
  T42_Parser  parser = &loader->parser;
  FT_Memory   memory = parser->root.memory;
  FT_Byte*    cur;
  FT_Byte*    limit  = parser->root.limit;
  FT_Error    error;
  FT_Int      num_tables = 0;
  FT_ULong    count;

  FT_Long     n, string_size, old_string_size, real_size;
  FT_Byte*    string_buf = NULL;
  FT_Bool     allocated  = 0;

  T42_Load_Status  status;


  /* The format is                                */
  /*                                              */
  /*   /sfnts [ <hexstring> <hexstring> ... ] def */
  /*                                              */
  /* or                                           */
  /*                                              */
  /*   /sfnts [                                   */
  /*      <num_bin_bytes> RD <binary data>        */
  /*      <num_bin_bytes> RD <binary data>        */
  /*      ...                                     */
  /*   ] def                                      */
  /*                                              */
  /* with exactly one space after the `RD' token. */

  T1_Skip_Spaces( parser );

  if ( parser->root.cursor >= limit || *parser->root.cursor++ != '[' )
  {
    FT_ERROR(( "t42_parse_sfnts: can't find begin of sfnts vector\n" ));
    error = FT_THROW( Invalid_File_Format );
    goto Fail;
  }

  T1_Skip_Spaces( parser );
  status          = BEFORE_START;
  string_size     = 0;
  old_string_size = 0;
  count           = 0;

  while ( parser->root.cursor < limit )
  {
    cur = parser->root.cursor;

    if ( *cur == ']' )
    {
      parser->root.cursor++;
      goto Exit;
    }

    else if ( *cur == '<' )
    {
      T1_Skip_PS_Token( parser );
      if ( parser->root.error )
        goto Exit;

      /* don't include delimiters */
      string_size = (FT_Long)( ( parser->root.cursor - cur - 2 + 1 ) / 2 );
      if ( FT_REALLOC( string_buf, old_string_size, string_size ) )
        goto Fail;

      allocated = 1;

      parser->root.cursor = cur;
      (void)T1_ToBytes( parser, string_buf, string_size, &real_size, 1 );
      old_string_size = string_size;
      string_size = real_size;
    }

    else if ( ft_isdigit( *cur ) )
    {
      if ( allocated )
      {
        FT_ERROR(( "t42_parse_sfnts: "
                   "can't handle mixed binary and hex strings\n" ));
        error = FT_THROW( Invalid_File_Format );
        goto Fail;
      }

      string_size = T1_ToInt( parser );
      if ( string_size < 0 )
      {
        FT_ERROR(( "t42_parse_sfnts: invalid string size\n" ));
        error = FT_THROW( Invalid_File_Format );
        goto Fail;
      }

      T1_Skip_PS_Token( parser );             /* `RD' */
      if ( parser->root.error )
        return;

      string_buf = parser->root.cursor + 1;   /* one space after `RD' */

      if ( limit - parser->root.cursor < string_size )
      {
        FT_ERROR(( "t42_parse_sfnts: too much binary data\n" ));
        error = FT_THROW( Invalid_File_Format );
        goto Fail;
      }
      else
        parser->root.cursor += string_size + 1;
    }

    if ( !string_buf )
    {
      FT_ERROR(( "t42_parse_sfnts: invalid data in sfnts array\n" ));
      error = FT_THROW( Invalid_File_Format );
      goto Fail;
    }

    /* A string can have a trailing zero (odd) byte for padding. */
    /* Ignore it.                                                */
    if ( ( string_size & 1 ) && string_buf[string_size - 1] == 0 )
      string_size--;

    if ( !string_size )
    {
      FT_ERROR(( "t42_parse_sfnts: invalid string\n" ));
      error = FT_THROW( Invalid_File_Format );
      goto Fail;
    }

    for ( n = 0; n < string_size; n++ )
    {
      switch ( status )
      {
      case BEFORE_START:
        /* load offset table, 12 bytes */
        if ( count < 12 )
        {
          face->ttf_data[count++] = string_buf[n];
          continue;
        }
        else
        {
          num_tables     = 16 * face->ttf_data[4] + face->ttf_data[5];
          status         = BEFORE_TABLE_DIR;
          face->ttf_size = 12 + 16 * num_tables;

          if ( FT_REALLOC( face->ttf_data, 12, face->ttf_size ) )
            goto Fail;
        }
        /* fall through */

      case BEFORE_TABLE_DIR:
        /* the offset table is read; read the table directory */
        if ( count < face->ttf_size )
        {
          face->ttf_data[count++] = string_buf[n];
          continue;
        }
        else
        {
          int       i;
          FT_ULong  len;


          for ( i = 0; i < num_tables; i++ )
          {
            FT_Byte*  p = face->ttf_data + 12 + 16 * i + 12;


            len = FT_PEEK_ULONG( p );

            /* Pad to a 4-byte boundary length */
            face->ttf_size += ( len + 3 ) & ~3;
          }

          status = OTHER_TABLES;

          /* there are no more than 256 tables, so no size check here */
          if ( FT_REALLOC( face->ttf_data, 12 + 16 * num_tables,
                           face->ttf_size + 1 ) )
            goto Fail;
        }
        /* fall through */

      case OTHER_TABLES:
        /* all other tables are just copied */
        if ( count >= face->ttf_size )
        {
          FT_ERROR(( "t42_parse_sfnts: too much binary data\n" ));
          error = FT_THROW( Invalid_File_Format );
          goto Fail;
        }
        face->ttf_data[count++] = string_buf[n];
      }
    }

    T1_Skip_Spaces( parser );
  }

  /* if control reaches this point, the format was not valid */
  error = FT_THROW( Invalid_File_Format );

Fail:
  parser->root.error = error;

Exit:
  if ( allocated )
    FT_FREE( string_buf );
}

