  if ( !pathname )
    return FT_Err_Invalid_Argument;

  args.flags    = FT_OPEN_PATHNAME;
  args.pathname = (char*)pathname;
  args.stream   = NULL;

  return FT_Open_Face( library, &args, face_index, aface );
}

