static void texImage2DResourceSafe(size_t width, size_t height)
{
    const int pixelSize = 4; // RGBA
    OwnArrayPtr<unsigned char> zero;
    if (width && height) {
        unsigned int size = width * height * pixelSize;
        zero = adoptArrayPtr(new unsigned char[size]);
        memset(zero.get(), 0, size);
    }
    GL_CMD(glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, width, height, 0, GL_RGBA, GL_UNSIGNED_BYTE, zero.get()))
}

void BitmapTextureGL::updateContents(PixelFormat pixelFormat, const IntRect& rect, void* bits)
{
    GL_CMD(glBindTexture(GL_TEXTURE_2D, m_id))
#ifdef TEXMAP_OPENGL_ES_2
    bool shouldSwizzle = false;
#endif

    GLint glFormat = GL_RGBA;
    switch (pixelFormat) {
    case RGBAFormat:
        glFormat = GL_RGBA;
        break;
    case RGBFormat:
        glFormat = GL_RGB;
        break;
    case BGRAFormat:
#ifdef TEXMAP_OPENGL_ES_2
        shouldSwizzle = true;
        glFormat = GL_RGBA;
#else
        glFormat = GL_BGRA;
#endif
        break;
    case BGRFormat:
#ifdef TEXMAP_OPENGL_ES_2
        shouldSwizzle = true;
        glFormat = GL_RGB;
#else
        glFormat = GL_BGR;
#endif
         break;
    }

#ifdef TEXMAP_OPENGL_ES_2
    if (shouldSwizzle)
        swizzleBGRAToRGBA(static_cast<uint32_t*>(bits), rect.size());
#endif
    GL_CMD(glTexSubImage2D(GL_TEXTURE_2D, 0, rect.x(), rect.y(), rect.width(), rect.height(), glFormat, GL_UNSIGNED_BYTE, bits))
}

void CountOriginType(const std::set<GURL>& origins,
                     SpecialStoragePolicy* policy,
                     size_t* protected_origins,
                     size_t* unlimited_origins) {
  DCHECK(protected_origins);
  DCHECK(unlimited_origins);
  *protected_origins = 0;
  *unlimited_origins = 0;
  if (!policy)
    return;
  for (std::set<GURL>::const_iterator itr = origins.begin();
       itr != origins.end();
       ++itr) {
    if (policy->IsStorageProtected(*itr))
      ++*protected_origins;
    if (policy->IsStorageUnlimited(*itr))
      ++*unlimited_origins;
  }
}

