void WorkerGlobalScopeFileSystem::webkitRequestFileSystem(WorkerGlobalScope& worker, int type, long long size, PassOwnPtr<FileSystemCallback> successCallback, PassOwnPtr<ErrorCallback> errorCallback)
{
    ExecutionContext* secureContext = worker.executionContext();
    if (!secureContext->securityOrigin()->canAccessFileSystem()) {
        DOMFileSystem::scheduleCallback(&worker, errorCallback, FileError::create(FileError::SECURITY_ERR));
        return;
    }

    FileSystemType fileSystemType = static_cast<FileSystemType>(type);
    if (!DOMFileSystemBase::isValidType(fileSystemType)) {
        DOMFileSystem::scheduleCallback(&worker, errorCallback, FileError::create(FileError::INVALID_MODIFICATION_ERR));
        return;
    }

    LocalFileSystem::from(worker)->requestFileSystem(&worker, fileSystemType, size, FileSystemCallbacks::create(successCallback, errorCallback, &worker, fileSystemType));
}

bool WaitForExtensionViewsToLoad() {

  content::NotificationRegistrar registrar;
  registrar.Add(this, chrome::NOTIFICATION_EXTENSION_HOST_DID_STOP_LOADING,
                content::NotificationService::AllSources());
  base::CancelableClosure timeout(
      base::Bind(&TimeoutCallback, "Extension host load timed out."));
  MessageLoop::current()->PostDelayedTask(
      FROM_HERE, timeout.callback(), base::TimeDelta::FromSeconds(4));

  ExtensionProcessManager* manager =
      extensions::ExtensionSystem::Get(browser()->profile())->
          process_manager();
  ExtensionProcessManager::ViewSet all_views = manager->GetAllViews();
  for (ExtensionProcessManager::ViewSet::const_iterator iter =
           all_views.begin();
       iter != all_views.end();) {
    if (!(*iter)->IsLoading())
      ++iter;
    else
      content::RunMessageLoop();
  }

  timeout.Cancel();
  return true;
}

scoped_ptr<cc::OutputSurface> RenderViewImpl::CreateOutputSurface() {
  WebKit::WebGraphicsContext3D::Attributes attributes;
  attributes.antialias = false;
  attributes.shareResources = true;
  attributes.noAutomaticFlushes = true;
  WebGraphicsContext3D* context = CreateGraphicsContext3D(attributes);
  if (!context)
    return scoped_ptr<cc::OutputSurface>();

  const CommandLine& command_line = *CommandLine::ForCurrentProcess();
  if (command_line.HasSwitch(switches::kEnableSoftwareCompositingGLAdapter)) {
      return scoped_ptr<cc::OutputSurface>(
          new CompositorOutputSurface(routing_id(), NULL,
              new CompositorSoftwareOutputDeviceGLAdapter(context)));
  } else {
      bool composite_to_mailbox =
          command_line.HasSwitch(cc::switches::kCompositeToMailbox);
      DCHECK(!composite_to_mailbox || command_line.HasSwitch(
          cc::switches::kEnableCompositorFrameMessage));
      DCHECK(!composite_to_mailbox || is_threaded_compositing_enabled_);
      return scoped_ptr<cc::OutputSurface>(composite_to_mailbox ?
          new MailboxOutputSurface(routing_id(), context, NULL) :
              new CompositorOutputSurface(routing_id(), context, NULL));
  }
}

