scoped_refptr<VASurface> VaapiJpegDecoder::Decode(
    base::span<const uint8_t> encoded_image,
    VaapiImageDecodeStatus* status) {
 if (!vaapi_wrapper_) {
   VLOGF(1) << "VaapiJpegDecoder has not been initialized";
   *status = VaapiImageDecodeStatus::kInvalidState;
   return nullptr;
 }

 JpegParseResult parse_result;
 if (!ParseJpegPicture(encoded_image.data(), encoded_image.size(),
                       &parse_result)) {
   VLOGF(1) << "ParseJpegPicture failed";
   *status = VaapiImageDecodeStatus::kParseJpegFailed;
   return nullptr;
 }

 const unsigned int picture_va_rt_format =
     VaSurfaceFormatForJpeg(parse_result.frame_header);
 if (picture_va_rt_format == kInvalidVaRtFormat) {
   VLOGF(1) << "Unsupported subsampling";
   *status = VaapiImageDecodeStatus::kUnsupportedSubsampling;
   return nullptr;
 }

 if (!IsVaapiSupportedJpeg(parse_result)) {
   VLOGF(1) << "The supplied JPEG is unsupported";
   *status = VaapiImageDecodeStatus::kUnsupportedJpeg;
   return nullptr;
 }

 const gfx::Size new_coded_size(
     base::strict_cast<int>(parse_result.frame_header.coded_width),
     base::strict_cast<int>(parse_result.frame_header.coded_height));
 if (new_coded_size != coded_size_ || va_surface_id_ == VA_INVALID_SURFACE ||
     picture_va_rt_format != va_rt_format_) {
   vaapi_wrapper_->DestroyContextAndSurfaces(
       std::vector<VASurfaceID>({va_surface_id_}));
   va_surface_id_ = VA_INVALID_SURFACE;
   va_rt_format_ = picture_va_rt_format;

   std::vector<VASurfaceID> va_surfaces;
   if (!vaapi_wrapper_->CreateContextAndSurfaces(va_rt_format_, new_coded_size,
                                                 1, &va_surfaces)) {
     VLOGF(1) << "Could not create the context or the surface";
     *status = VaapiImageDecodeStatus::kSurfaceCreationFailed;
     return nullptr;
   }
   va_surface_id_ = va_surfaces[0];
   coded_size_ = new_coded_size;
 }

 VAPictureParameterBufferJPEGBaseline pic_param{};
 FillPictureParameters(parse_result.frame_header, &pic_param);
 if (!vaapi_wrapper_->SubmitBuffer(VAPictureParameterBufferType, &pic_param)) {
   VLOGF(1) << "Could not submit VAPictureParameterBufferType";
   *status = VaapiImageDecodeStatus::kSubmitPicParamsFailed;
   return nullptr;
 }

 VAIQMatrixBufferJPEGBaseline iq_matrix{};
 FillIQMatrix(parse_result.q_table, &iq_matrix);
 if (!vaapi_wrapper_->SubmitBuffer(VAIQMatrixBufferType, &iq_matrix)) {
   VLOGF(1) << "Could not submit VAIQMatrixBufferType";
   *status = VaapiImageDecodeStatus::kSubmitIQMatrixFailed;
   return nullptr;
 }

 VAHuffmanTableBufferJPEGBaseline huffman_table{};
 FillHuffmanTable(parse_result.dc_table, parse_result.ac_table,
                  &huffman_table);
 if (!vaapi_wrapper_->SubmitBuffer(VAHuffmanTableBufferType, &huffman_table)) {
   VLOGF(1) << "Could not submit VAHuffmanTableBufferType";
   *status = VaapiImageDecodeStatus::kSubmitHuffmanFailed;
   return nullptr;
 }

 VASliceParameterBufferJPEGBaseline slice_param{};
 FillSliceParameters(parse_result, &slice_param);
 if (!vaapi_wrapper_->SubmitBuffer(VASliceParameterBufferType, &slice_param)) {
   VLOGF(1) << "Could not submit VASliceParameterBufferType";
   *status = VaapiImageDecodeStatus::kSubmitSliceParamsFailed;
   return nullptr;
 }

 if (!vaapi_wrapper_->SubmitBuffer(VASliceDataBufferType,
                                   parse_result.data_size,
                                   const_cast<char*>(parse_result.data))) {
   VLOGF(1) << "Could not submit VASliceDataBufferType";
   *status = VaapiImageDecodeStatus::kSubmitSliceDataFailed;
   return nullptr;
 }

 if (!vaapi_wrapper_->ExecuteAndDestroyPendingBuffers(va_surface_id_)) {
   VLOGF(1) << "Executing the decode failed";
   *status = VaapiImageDecodeStatus::kExecuteDecodeFailed;
   return nullptr;
 }

 *status = VaapiImageDecodeStatus::kSuccess;
 return base::MakeRefCounted<VASurface>(va_surface_id_, coded_size_,
                                        va_rt_format_,
                                         base::DoNothing() /* release_cb */);
}

HeadlessDevToolsManagerDelegate::GetWindowBounds(
    content::DevToolsAgentHost* agent_host,
    int session_id,
    int command_id,
    const base::DictionaryValue* params) {
  HeadlessWebContentsImpl* web_contents;
  const base::Value* window_id_value = params->FindKey("windowId");
  if (!window_id_value || !window_id_value->is_int())
    return CreateInvalidParamResponse(command_id, "windowId");
  web_contents = browser_->GetWebContentsForWindowId(window_id_value->GetInt());
  if (!web_contents) {
    return CreateErrorResponse(command_id, kErrorServerError,
                               "Browser window not found");
  }

  auto result = std::make_unique<base::DictionaryValue>();
  result->Set("bounds", CreateBoundsDict(web_contents));
  return CreateSuccessResponse(command_id, std::move(result));
}

bool HeadlessDevToolsManagerDelegate::HandleAsyncCommand(
    content::DevToolsAgentHost* agent_host,
    int session_id,
    base::DictionaryValue* command,
    const CommandCallback& callback) {
  DCHECK_CURRENTLY_ON(content::BrowserThread::UI);

  if (!browser_)
    return false;

  const base::Value* id_value = command->FindKey("id");
  const base::Value* method_value = command->FindKey("method");
  if (!id_value || !method_value)
    return false;

  auto find_it = async_command_map_.find(method_value->GetString());
  if (find_it == async_command_map_.end())
    return false;

  const base::DictionaryValue* params = nullptr;
  command->GetDictionary("params", &params);
  find_it->second.Run(agent_host, session_id, id_value->GetInt(), params,
                      callback);
  return true;
}

HeadlessDevToolsManagerDelegate::NetworkDisable(
    content::DevToolsAgentHost* agent_host,
    int session_id,
    int command_id,
    const base::DictionaryValue* params) {
  std::vector<HeadlessBrowserContext*> browser_contexts =
      browser_->GetAllBrowserContexts();
  if (browser_contexts.empty())
    return CreateSuccessResponse(command_id, nullptr);
  SetNetworkConditions(browser_contexts, HeadlessNetworkConditions());
  return CreateSuccessResponse(command_id, nullptr);
}

bool HeadlessPrintManager::OnMessageReceived(
    const IPC::Message& message,
    content::RenderFrameHost* render_frame_host) {
  if (!printing_rfh_ &&
      (message.type() == PrintHostMsg_GetDefaultPrintSettings::ID ||
       message.type() == PrintHostMsg_ScriptedPrint::ID)) {
    std::string type;
    switch (message.type()) {
      case PrintHostMsg_GetDefaultPrintSettings::ID:
        type = "GetDefaultPrintSettings";
        break;
      case PrintHostMsg_ScriptedPrint::ID:
        type = "ScriptedPrint";
        break;
      default:
        type = "Unknown";
        break;
    }
    DLOG(ERROR)
        << "Unexpected message received before GetPDFContents is called: "
        << type;

    render_frame_host->Send(IPC::SyncMessage::GenerateReply(&message));
    return true;
  }

  FrameDispatchHelper helper = {this, render_frame_host};
  bool handled = true;
  IPC_BEGIN_MESSAGE_MAP(HeadlessPrintManager, message)
    IPC_MESSAGE_HANDLER(PrintHostMsg_ShowInvalidPrinterSettingsError,
                        OnShowInvalidPrinterSettingsError)
    IPC_MESSAGE_HANDLER(PrintHostMsg_DidPrintDocument, OnDidPrintDocument)
    IPC_MESSAGE_FORWARD_DELAY_REPLY(
        PrintHostMsg_GetDefaultPrintSettings, &helper,
        FrameDispatchHelper::OnGetDefaultPrintSettings)
    IPC_MESSAGE_FORWARD_DELAY_REPLY(PrintHostMsg_ScriptedPrint, &helper,
                                    FrameDispatchHelper::OnScriptedPrint)
    IPC_MESSAGE_UNHANDLED(handled = false)
  IPC_END_MESSAGE_MAP()
  return handled || PrintManager::OnMessageReceived(message, render_frame_host);
}

void HeadlessPrintManager::OnShowInvalidPrinterSettingsError() {
  ReleaseJob(INVALID_PRINTER_SETTINGS);
}

std::string HeadlessPrintManager::PrintResultToString(PrintResult result) {
  switch (result) {
    case PRINT_SUCCESS:
      return std::string();  // no error message
    case PRINTING_FAILED:
      return "Printing failed";
    case INVALID_PRINTER_SETTINGS:
      return "Show invalid printer settings error";
    case INVALID_MEMORY_HANDLE:
      return "Invalid memory handle";
    case METAFILE_MAP_ERROR:
      return "Map to shared memory error";
    case METAFILE_INVALID_HEADER:
      return "Invalid metafile header";
    case METAFILE_GET_DATA_ERROR:
      return "Get data from metafile error";
    case SIMULTANEOUS_PRINT_ACTIVE:
      return "The previous printing job hasn't finished";
    case PAGE_RANGE_SYNTAX_ERROR:
      return "Page range syntax error";
    case PAGE_COUNT_EXCEEDED:
      return "Page range exceeds page count";
    default:
      NOTREACHED();
      return "Unknown PrintResult";
  }
}

void HeadlessPrintManager::ReleaseJob(PrintResult result) {
  if (!callback_) {
    DLOG(ERROR) << "ReleaseJob is called when callback_ is null. Check whether "
                   "ReleaseJob is called more than once.";
    return;
  }

  if (result == PRINT_SUCCESS)
    callback_.Run(result, std::move(data_));
  else
    callback_.Run(result, std::string());
  printing_rfh_->Send(new PrintMsg_PrintingDone(printing_rfh_->GetRoutingID(),
                                                result == PRINT_SUCCESS));
  Reset();
}

