#if BUILDFLAG(ENABLE_DESKTOP_IN_PRODUCT_HELP)
  if (controller()->GetToolbarModel()->ShouldDisplayURL()) {
    feature_engagement::NewTabTrackerFactory::GetInstance()
        ->GetForProfile(location_bar_view_->profile())
        ->OnOmniboxFocused();
  }
#endif
}

