status_t OMXCodec::allocateOutputBuffersFromNativeWindow() {
    OMX_PARAM_PORTDEFINITIONTYPE def;
 InitOMXParams(&def);
    def.nPortIndex = kPortIndexOutput;

 status_t err = mOMX->getParameter(
            mNode, OMX_IndexParamPortDefinition, &def, sizeof(def));
 if (err != OK) {
        CODEC_LOGE("getParameter failed: %d", err);
 return err;
 }

    sp<MetaData> meta = mSource->getFormat();

 int32_t rotationDegrees;
 if (!meta->findInt32(kKeyRotation, &rotationDegrees)) {
        rotationDegrees = 0;
 }

    OMX_U32 usage = 0;
    err = mOMX->getGraphicBufferUsage(mNode, kPortIndexOutput, &usage);
 if (err != 0) {
        ALOGW("querying usage flags from OMX IL component failed: %d", err);
        usage = 0;
 }

 if (mFlags & kEnableGrallocUsageProtected) {
        usage |= GRALLOC_USAGE_PROTECTED;
 }

    err = setNativeWindowSizeFormatAndUsage(
            mNativeWindow.get(),
            def.format.video.nFrameWidth,
            def.format.video.nFrameHeight,
            def.format.video.eColorFormat,
            rotationDegrees,
            usage | GRALLOC_USAGE_HW_TEXTURE | GRALLOC_USAGE_EXTERNAL_DISP);
 if (err != 0) {
 return err;
 }

 int minUndequeuedBufs = 0;
    err = mNativeWindow->query(mNativeWindow.get(),
            NATIVE_WINDOW_MIN_UNDEQUEUED_BUFFERS, &minUndequeuedBufs);
 if (err != 0) {
        ALOGE("NATIVE_WINDOW_MIN_UNDEQUEUED_BUFFERS query failed: %s (%d)",
                strerror(-err), -err);
 return err;
 }

    CODEC_LOGI("OMX-buffers: min=%u actual=%u undeq=%d+1",
            def.nBufferCountMin, def.nBufferCountActual, minUndequeuedBufs);

 for (OMX_U32 extraBuffers = 2 + 1; /* condition inside loop */; extraBuffers--) {
        OMX_U32 newBufferCount =
            def.nBufferCountMin + minUndequeuedBufs + extraBuffers;
        def.nBufferCountActual = newBufferCount;
        err = mOMX->setParameter(
                mNode, OMX_IndexParamPortDefinition, &def, sizeof(def));

 if (err == OK) {
            minUndequeuedBufs += extraBuffers;
 break;
 }

        CODEC_LOGW("setting nBufferCountActual to %u failed: %d",
                newBufferCount, err);
 /* exit condition */
 if (extraBuffers == 0) {
 return err;
 }
 }
    CODEC_LOGI("OMX-buffers: min=%u actual=%u undeq=%d+1",
            def.nBufferCountMin, def.nBufferCountActual, minUndequeuedBufs);

    err = native_window_set_buffer_count(
            mNativeWindow.get(), def.nBufferCountActual);
 if (err != 0) {
        ALOGE("native_window_set_buffer_count failed: %s (%d)", strerror(-err),
 -err);
 return err;
 }

    CODEC_LOGV("allocating %u buffers from a native window of size %u on "
 "output port", def.nBufferCountActual, def.nBufferSize);

 for (OMX_U32 i = 0; i < def.nBufferCountActual; i++) {
 ANativeWindowBuffer* buf;
        err = native_window_dequeue_buffer_and_wait(mNativeWindow.get(), &buf);
 if (err != 0) {
            ALOGE("dequeueBuffer failed: %s (%d)", strerror(-err), -err);
 break;
 }

        sp<GraphicBuffer> graphicBuffer(new GraphicBuffer(buf, false));
 BufferInfo info;
        info.mData = NULL;
        info.mSize = def.nBufferSize;
        info.mStatus = OWNED_BY_US;
        info.mMem = NULL;
        info.mMediaBuffer = new MediaBuffer(graphicBuffer);
        info.mMediaBuffer->setObserver(this);
        mPortBuffers[kPortIndexOutput].push(info);

        IOMX::buffer_id bufferId;
        err = mOMX->useGraphicBuffer(mNode, kPortIndexOutput, graphicBuffer,
 &bufferId);
 if (err != 0) {
            CODEC_LOGE("registering GraphicBuffer with OMX IL component "
 "failed: %d", err);
 break;
 }

        mPortBuffers[kPortIndexOutput].editItemAt(i).mBuffer = bufferId;

        CODEC_LOGV("registered graphic buffer with ID %u (pointer = %p)",
                bufferId, graphicBuffer.get());
 }

    OMX_U32 cancelStart;
    OMX_U32 cancelEnd;
 if (err != 0) {
        cancelStart = 0;
        cancelEnd = mPortBuffers[kPortIndexOutput].size();
 } else {
        cancelStart = def.nBufferCountActual - minUndequeuedBufs;
        cancelEnd = def.nBufferCountActual;
 }

 for (OMX_U32 i = cancelStart; i < cancelEnd; i++) {
 BufferInfo *info = &mPortBuffers[kPortIndexOutput].editItemAt(i);
        cancelBufferToNativeWindow(info);
 }

 return err;
}

void OMXCodec::on_message(const omx_message &msg) {
 if (mState == ERROR) {
 /*
         * only drop EVENT messages, EBD and FBD are still
         * processed for bookkeeping purposes
         */
 if (msg.type == omx_message::EVENT) {
            ALOGW("Dropping OMX EVENT message - we're in ERROR state.");
 return;
 }
 }

 switch (msg.type) {
 case omx_message::EVENT:
 {
            onEvent(
                 msg.u.event_data.event, msg.u.event_data.data1,
                 msg.u.event_data.data2);

 break;
 }

 case omx_message::EMPTY_BUFFER_DONE:
 {
            IOMX::buffer_id buffer = msg.u.extended_buffer_data.buffer;

            CODEC_LOGV("EMPTY_BUFFER_DONE(buffer: %u)", buffer);

 Vector<BufferInfo> *buffers = &mPortBuffers[kPortIndexInput];
 size_t i = 0;
 while (i < buffers->size() && (*buffers)[i].mBuffer != buffer) {
 ++i;
 }

            CHECK(i < buffers->size());
 if ((*buffers)[i].mStatus != OWNED_BY_COMPONENT) {
                ALOGW("We already own input buffer %u, yet received "
 "an EMPTY_BUFFER_DONE.", buffer);
 }

 BufferInfo* info = &buffers->editItemAt(i);
            info->mStatus = OWNED_BY_US;

 if (info->mMediaBuffer != NULL) {
                info->mMediaBuffer->release();
                info->mMediaBuffer = NULL;
 }

 if (mPortStatus[kPortIndexInput] == DISABLING) {
                CODEC_LOGV("Port is disabled, freeing buffer %u", buffer);

 status_t err = freeBuffer(kPortIndexInput, i);
                CHECK_EQ(err, (status_t)OK);
 } else if (mState != ERROR
 && mPortStatus[kPortIndexInput] != SHUTTING_DOWN) {
                CHECK_EQ((int)mPortStatus[kPortIndexInput], (int)ENABLED);

 if (mFlags & kUseSecureInputBuffers) {
                    drainAnyInputBuffer();
 } else {
                    drainInputBuffer(&buffers->editItemAt(i));
 }
 }
 break;
 }

 case omx_message::FILL_BUFFER_DONE:
 {
            IOMX::buffer_id buffer = msg.u.extended_buffer_data.buffer;
            OMX_U32 flags = msg.u.extended_buffer_data.flags;

            CODEC_LOGV("FILL_BUFFER_DONE(buffer: %u, size: %u, flags: 0x%08x, timestamp: %lld us (%.2f secs))",
                 buffer,
                 msg.u.extended_buffer_data.range_length,
                 flags,
                 msg.u.extended_buffer_data.timestamp,
                 msg.u.extended_buffer_data.timestamp / 1E6);

 Vector<BufferInfo> *buffers = &mPortBuffers[kPortIndexOutput];
 size_t i = 0;
 while (i < buffers->size() && (*buffers)[i].mBuffer != buffer) {
 ++i;
 }

            CHECK(i < buffers->size());
 BufferInfo *info = &buffers->editItemAt(i);

 if (info->mStatus != OWNED_BY_COMPONENT) {
                ALOGW("We already own output buffer %u, yet received "
 "a FILL_BUFFER_DONE.", buffer);
 }

            info->mStatus = OWNED_BY_US;

 if (mPortStatus[kPortIndexOutput] == DISABLING) {
                CODEC_LOGV("Port is disabled, freeing buffer %u", buffer);

 status_t err = freeBuffer(kPortIndexOutput, i);
                CHECK_EQ(err, (status_t)OK);

#if 0
 } else if (mPortStatus[kPortIndexOutput] == ENABLED
 && (flags & OMX_BUFFERFLAG_EOS)) {
                CODEC_LOGV("No more output data.");
                mNoMoreOutputData = true;
                mBufferFilled.signal();
#endif
 } else if (mPortStatus[kPortIndexOutput] != SHUTTING_DOWN) {
                CHECK_EQ((int)mPortStatus[kPortIndexOutput], (int)ENABLED);

 MediaBuffer *buffer = info->mMediaBuffer;
 bool isGraphicBuffer = buffer->graphicBuffer() != NULL;

 if (!isGraphicBuffer
 && msg.u.extended_buffer_data.range_offset
 + msg.u.extended_buffer_data.range_length
 > buffer->size()) {
                    CODEC_LOGE(
 "Codec lied about its buffer size requirements, "
 "sending a buffer larger than the originally "
 "advertised size in FILL_BUFFER_DONE!");
 }
                buffer->set_range(
                        msg.u.extended_buffer_data.range_offset,
                        msg.u.extended_buffer_data.range_length);

                buffer->meta_data()->clear();

                buffer->meta_data()->setInt64(
                        kKeyTime, msg.u.extended_buffer_data.timestamp);

 if (msg.u.extended_buffer_data.flags & OMX_BUFFERFLAG_SYNCFRAME) {
                    buffer->meta_data()->setInt32(kKeyIsSyncFrame, true);
 }
 bool isCodecSpecific = false;
 if (msg.u.extended_buffer_data.flags & OMX_BUFFERFLAG_CODECCONFIG) {
                    buffer->meta_data()->setInt32(kKeyIsCodecConfig, true);
                    isCodecSpecific = true;
 }

 if (isGraphicBuffer || mQuirks & kOutputBuffersAreUnreadable) {
                    buffer->meta_data()->setInt32(kKeyIsUnreadable, true);
 }

                buffer->meta_data()->setInt32(
                        kKeyBufferID,
                        msg.u.extended_buffer_data.buffer);

 if (msg.u.extended_buffer_data.flags & OMX_BUFFERFLAG_EOS) {
                    CODEC_LOGV("No more output data.");
                    mNoMoreOutputData = true;
 }

 if (mIsEncoder && mIsVideo) {
 int64_t decodingTimeUs = isCodecSpecific? 0: getDecodingTimeUs();
                    buffer->meta_data()->setInt64(kKeyDecodingTime, decodingTimeUs);
 }

 if (mTargetTimeUs >= 0) {
                    CHECK(msg.u.extended_buffer_data.timestamp <= mTargetTimeUs);

 if (msg.u.extended_buffer_data.timestamp < mTargetTimeUs) {
                        CODEC_LOGV(
 "skipping output buffer at timestamp %lld us",
                                msg.u.extended_buffer_data.timestamp);

                        fillOutputBuffer(info);
 break;
 }

                    CODEC_LOGV(
 "returning output buffer at target timestamp "
 "%lld us",
                            msg.u.extended_buffer_data.timestamp);

                    mTargetTimeUs = -1;
 }

                mFilledBuffers.push_back(i);
                mBufferFilled.signal();
 if (mIsEncoder) {
                    sched_yield();
 }
 }

 break;
 }

 default:
 {
            CHECK(!"should not be here.");
 break;
 }
 }
}

status_t OMXCodec::read(
 MediaBuffer **buffer, const ReadOptions *options) {
 status_t err = OK;
 *buffer = NULL;

 Mutex::Autolock autoLock(mLock);

 if (mState != EXECUTING && mState != RECONFIGURING) {
 return UNKNOWN_ERROR;
 }

 bool seeking = false;
 int64_t seekTimeUs;
 ReadOptions::SeekMode seekMode;
 if (options && options->getSeekTo(&seekTimeUs, &seekMode)) {
        seeking = true;
 }

 if (mInitialBufferSubmit) {
        mInitialBufferSubmit = false;

 if (seeking) {
            CHECK(seekTimeUs >= 0);
            mSeekTimeUs = seekTimeUs;
            mSeekMode = seekMode;

            seeking = false;
            mPaused = false;
 }

        drainInputBuffers();

 if (mState == EXECUTING) {
            fillOutputBuffers();
 }
 }

 if (seeking) {
 while (mState == RECONFIGURING) {
 if ((err = waitForBufferFilled_l()) != OK) {
 return err;
 }
 }

 if (mState != EXECUTING) {
 return UNKNOWN_ERROR;
 }

        CODEC_LOGV("seeking to %" PRId64 " us (%.2f secs)", seekTimeUs, seekTimeUs / 1E6);

        mSignalledEOS = false;

        CHECK(seekTimeUs >= 0);
        mSeekTimeUs = seekTimeUs;
        mSeekMode = seekMode;

        mFilledBuffers.clear();

        CHECK_EQ((int)mState, (int)EXECUTING);

 bool emulateInputFlushCompletion = !flushPortAsync(kPortIndexInput);
 bool emulateOutputFlushCompletion = !flushPortAsync(kPortIndexOutput);

 if (emulateInputFlushCompletion) {
            onCmdComplete(OMX_CommandFlush, kPortIndexInput);
 }

 if (emulateOutputFlushCompletion) {
            onCmdComplete(OMX_CommandFlush, kPortIndexOutput);
 }

 while (mSeekTimeUs >= 0) {
 if ((err = waitForBufferFilled_l()) != OK) {
 return err;
 }
 }
 }

 while (mState != ERROR && !mNoMoreOutputData && mFilledBuffers.empty()) {
 if ((err = waitForBufferFilled_l()) != OK) {
 return err;
 }
 }

 if (mState == ERROR) {
 return UNKNOWN_ERROR;
 }

 if (mFilledBuffers.empty()) {
 return mSignalledEOS ? mFinalStatus : ERROR_END_OF_STREAM;
 }

 if (mOutputPortSettingsHaveChanged) {
        mOutputPortSettingsHaveChanged = false;

 return INFO_FORMAT_CHANGED;
 }

 size_t index = *mFilledBuffers.begin();
    mFilledBuffers.erase(mFilledBuffers.begin());

 BufferInfo *info = &mPortBuffers[kPortIndexOutput].editItemAt(index);
    CHECK_EQ((int)info->mStatus, (int)OWNED_BY_US);
    info->mStatus = OWNED_BY_CLIENT;

    info->mMediaBuffer->add_ref();
 if (mSkipCutBuffer != NULL) {
        mSkipCutBuffer->submit(info->mMediaBuffer);
 }
 *buffer = info->mMediaBuffer;

 return OK;
}

void OMXCodec::setAMRFormat(bool isWAMR, int32_t bitRate) {
    OMX_U32 portIndex = mIsEncoder ? kPortIndexOutput : kPortIndexInput;

    OMX_AUDIO_PARAM_AMRTYPE def;
 InitOMXParams(&def);
    def.nPortIndex = portIndex;

 status_t err =
        mOMX->getParameter(mNode, OMX_IndexParamAudioAmr, &def, sizeof(def));

    CHECK_EQ(err, (status_t)OK);

    def.eAMRFrameFormat = OMX_AUDIO_AMRFrameFormatFSF;

    def.eAMRBandMode = pickModeFromBitRate(isWAMR, bitRate);
    err = mOMX->setParameter(mNode, OMX_IndexParamAudioAmr, &def, sizeof(def));
    CHECK_EQ(err, (status_t)OK);


 if (mIsEncoder) {
        sp<MetaData> format = mSource->getFormat();
 int32_t sampleRate;
 int32_t numChannels;
        CHECK(format->findInt32(kKeySampleRate, &sampleRate));
        CHECK(format->findInt32(kKeyChannelCount, &numChannels));

        setRawAudioFormat(kPortIndexInput, sampleRate, numChannels);
 }
}

