    imageDef->nFrameHeight = height;

 switch (format) {
 case OMX_COLOR_FormatYUV420PackedPlanar:
 case OMX_COLOR_FormatYUV411Planar:
 {
            def.nBufferSize = (width * height * 3) / 2;
 break;
 }

 case OMX_COLOR_FormatCbYCrY:
 {
            def.nBufferSize = width * height * 2;
 break;
