 status_t ret = mMediaRecorder->setVideoSource(vs);

 if (OK != ret) {
        ALOGV("setVideoSource failed: %d", ret);
        mCurrentState = MEDIA_RECORDER_ERROR;
 return ret;
 }
    mIsVideoSourceSet = true;
