sp<ABuffer> NuPlayer::GenericSource::mediaBufferToABuffer(
 MediaBuffer* mb,
        media_track_type trackType,
 int64_t *actualTimeUs) {
 bool audio = trackType == MEDIA_TRACK_TYPE_AUDIO;
 size_t outLength = mb->range_length();

 if (audio && mAudioIsVorbis) {
        outLength += sizeof(int32_t);
 }

    sp<ABuffer> ab;
 if (mIsWidevine && !audio) {
        ab = new ABuffer(NULL, mb->range_length());
        mb->add_ref();
        ab->setMediaBufferBase(mb);
 } else {
        ab = new ABuffer(outLength);
        memcpy(ab->data(),
 (const uint8_t *)mb->data() + mb->range_offset(),
               mb->range_length());
 }

 if (audio && mAudioIsVorbis) {
 int32_t numPageSamples;
 if (!mb->meta_data()->findInt32(kKeyValidSamples, &numPageSamples)) {
            numPageSamples = -1;
 }

 uint8_t* abEnd = ab->data() + mb->range_length();
        memcpy(abEnd, &numPageSamples, sizeof(numPageSamples));
 }

    sp<AMessage> meta = ab->meta();

 int64_t timeUs;
    CHECK(mb->meta_data()->findInt64(kKeyTime, &timeUs));
    meta->setInt64("timeUs", timeUs);

 if (trackType == MEDIA_TRACK_TYPE_TIMEDTEXT) {
 const char *mime;
        CHECK(mTimedTextTrack.mSource != NULL
 && mTimedTextTrack.mSource->getFormat()->findCString(kKeyMIMEType, &mime));
        meta->setString("mime", mime);
 }

 int64_t durationUs;
 if (mb->meta_data()->findInt64(kKeyDuration, &durationUs)) {
        meta->setInt64("durationUs", durationUs);
 }

 if (trackType == MEDIA_TRACK_TYPE_SUBTITLE) {
        meta->setInt32("trackIndex", mSubtitleTrack.mIndex);
 }

 if (actualTimeUs) {
 *actualTimeUs = timeUs;
 }

    mb->release();
    mb = NULL;

 return ab;
}

void NuPlayer::GenericSource::onMessageReceived(const sp<AMessage> &msg) {
 switch (msg->what()) {
 case kWhatPrepareAsync:
 {
          onPrepareAsync();
 break;
 }
 case kWhatFetchSubtitleData:
 {
          fetchTextData(kWhatSendSubtitleData, MEDIA_TRACK_TYPE_SUBTITLE,
                  mFetchSubtitleDataGeneration, mSubtitleTrack.mPackets, msg);
 break;
 }

 case kWhatFetchTimedTextData:
 {
          fetchTextData(kWhatSendTimedTextData, MEDIA_TRACK_TYPE_TIMEDTEXT,
                  mFetchTimedTextDataGeneration, mTimedTextTrack.mPackets, msg);
 break;
 }

 case kWhatSendSubtitleData:
 {
          sendTextData(kWhatSubtitleData, MEDIA_TRACK_TYPE_SUBTITLE,
                  mFetchSubtitleDataGeneration, mSubtitleTrack.mPackets, msg);
 break;
 }

 case kWhatSendTimedTextData:
 {
          sendTextData(kWhatTimedTextData, MEDIA_TRACK_TYPE_TIMEDTEXT,
                  mFetchTimedTextDataGeneration, mTimedTextTrack.mPackets, msg);
 break;
 }

 case kWhatChangeAVSource:
 {
 int32_t trackIndex;
          CHECK(msg->findInt32("trackIndex", &trackIndex));
 const sp<MediaSource> source = mSources.itemAt(trackIndex);

 Track* track;
 const char *mime;
          media_track_type trackType, counterpartType;
          sp<MetaData> meta = source->getFormat();
          meta->findCString(kKeyMIMEType, &mime);
 if (!strncasecmp(mime, "audio/", 6)) {
              track = &mAudioTrack;
              trackType = MEDIA_TRACK_TYPE_AUDIO;
              counterpartType = MEDIA_TRACK_TYPE_VIDEO;;
 } else {
              CHECK(!strncasecmp(mime, "video/", 6));
              track = &mVideoTrack;
              trackType = MEDIA_TRACK_TYPE_VIDEO;
              counterpartType = MEDIA_TRACK_TYPE_AUDIO;;
 }


 if (track->mSource != NULL) {
              track->mSource->stop();
 }
          track->mSource = source;
          track->mSource->start();
          track->mIndex = trackIndex;

 status_t avail;
 if (!track->mPackets->hasBufferAvailable(&avail)) {
              TRESPASS();
 break;
 }

 int64_t timeUs, actualTimeUs;
 const bool formatChange = true;
          sp<AMessage> latestMeta = track->mPackets->getLatestEnqueuedMeta();
          CHECK(latestMeta != NULL && latestMeta->findInt64("timeUs", &timeUs));
          readBuffer(trackType, timeUs, &actualTimeUs, formatChange);
          readBuffer(counterpartType, -1, NULL, formatChange);
          ALOGV("timeUs %lld actualTimeUs %lld", timeUs, actualTimeUs);

 break;
 }
 case kWhatPollBuffering:
 {
 int32_t generation;
          CHECK(msg->findInt32("generation", &generation));
 if (generation == mPollBufferingGeneration) {
              onPollBuffering();
 }
 break;
 }

 case kWhatGetFormat:
 {
          onGetFormatMeta(msg);
 break;
 }

 case kWhatGetSelectedTrack:
 {
          onGetSelectedTrack(msg);
 break;
 }

 case kWhatSelectTrack:
 {
          onSelectTrack(msg);
 break;
 }

 case kWhatSeek:
 {
          onSeek(msg);
 break;
 }

 case kWhatReadBuffer:
 {
          onReadBuffer(msg);
 break;
 }

 case kWhatStopWidevine:
 {
          mStopRead = true;
 if (mVideoTrack.mSource != NULL) {
              mVideoTrack.mPackets->clear();
 }
          sp<AMessage> response = new AMessage;
 uint32_t replyID;
          CHECK(msg->senderAwaitsResponse(&replyID));
          response->postReply(replyID);
 break;
 }
 default:
 Source::onMessageReceived(msg);
 break;
 }
}

SYSCALL_DEFINE1(getsid, pid_t, pid)
{
 struct task_struct *p;
 struct pid *sid;
 int retval;

	rcu_read_lock();
 if (!pid)
		sid = task_session(current);
 else {
		retval = -ESRCH;
		p = find_task_by_vpid(pid);
 if (!p)
 goto out;
		sid = task_session(p);
 if (!sid)
 goto out;

		retval = security_task_getsid(p);
 if (retval)
 goto out;
 }
	retval = pid_vnr(sid);
out:
	rcu_read_unlock();
 return retval;
}

static void migrate_to_reboot_cpu(void)
{
 /* The boot cpu is always logical cpu 0 */
 int cpu = 0;

	cpu_hotplug_disable();

 /* Make certain the cpu I'm about to reboot on is online */
 if (!cpu_online(cpu))
		cpu = cpumask_first(cpu_online_mask);

 /* Prevent races with other tasks migrating this task */
	current->flags |= PF_NO_SETAFFINITY;

 /* Make certain I only run on the appropriate processor */
	set_cpus_allowed_ptr(current, cpumask_of(cpu));
}

int orderly_poweroff(bool force)
{
 int argc;
 char **argv = argv_split(GFP_ATOMIC, poweroff_cmd, &argc);
 static char *envp[] = {
 "HOME=/",
 "PATH=/sbin:/bin:/usr/sbin:/usr/bin",
		NULL
 };
 int ret = -ENOMEM;
 struct subprocess_info *info;

 if (argv == NULL) {
		printk(KERN_WARNING "%s failed to allocate memory for \"%s\"\n",
		       __func__, poweroff_cmd);
 goto out;
 }

	info = call_usermodehelper_setup(argv[0], argv, envp, GFP_ATOMIC);
 if (info == NULL) {
		argv_free(argv);
 goto out;
 }

	call_usermodehelper_setfns(info, NULL, argv_cleanup, NULL);

	ret = call_usermodehelper_exec(info, UMH_NO_WAIT);

  out:
 if (ret && force) {
		printk(KERN_WARNING "Failed to start orderly shutdown: "
 "forcing the issue\n");

 /* I guess this should try to kick off some daemon to
		   sync and poweroff asap.  Or not even bother syncing
		   if we're doing an emergency shutdown? */
		emergency_sync();
		kernel_power_off();
 }

 return ret;
}

void RIL_onUnsolicitedResponse(int unsolResponse, const void *data,
 size_t datalen, RIL_SOCKET_ID socket_id)
#else
extern "C"
void RIL_onUnsolicitedResponse(int unsolResponse, const void *data,
 size_t datalen)
#endif
{
 int unsolResponseIndex;
 int ret;
 int64_t timeReceived = 0;
 bool shouldScheduleTimeout = false;
    RIL_RadioState newState;
    RIL_SOCKET_ID soc_id = RIL_SOCKET_1;

#if defined(ANDROID_MULTI_SIM)
    soc_id = socket_id;
#endif


 if (s_registerCalled == 0) {
        RLOGW("RIL_onUnsolicitedResponse called before RIL_register");
 return;
 }

    unsolResponseIndex = unsolResponse - RIL_UNSOL_RESPONSE_BASE;

 if ((unsolResponseIndex < 0)
 || (unsolResponseIndex >= (int32_t)NUM_ELEMS(s_unsolResponses))) {
        RLOGE("unsupported unsolicited response code %d", unsolResponse);
 return;
 }

 switch (s_unsolResponses[unsolResponseIndex].wakeType) {
 case WAKE_PARTIAL:
            grabPartialWakeLock();
            shouldScheduleTimeout = true;
 break;

 case DONT_WAKE:
 default:
            shouldScheduleTimeout = false;
 break;
 }

 if (unsolResponse == RIL_UNSOL_NITZ_TIME_RECEIVED) {
        timeReceived = elapsedRealtime();
 }

    appendPrintBuf("[UNSL]< %s", requestToString(unsolResponse));

 Parcel p;
 if (s_callbacks.version >= 13
 && s_unsolResponses[unsolResponseIndex].wakeType == WAKE_PARTIAL) {
        p.writeInt32 (RESPONSE_UNSOLICITED_ACK_EXP);
 } else {
        p.writeInt32 (RESPONSE_UNSOLICITED);
 }
    p.writeInt32 (unsolResponse);

    ret = s_unsolResponses[unsolResponseIndex]
 .responseFunction(p, const_cast<void*>(data), datalen);
 if (ret != 0) {
 goto error_exit;
 }

 switch(unsolResponse) {
 case RIL_UNSOL_RESPONSE_RADIO_STATE_CHANGED:
            newState = processRadioState(CALL_ONSTATEREQUEST(soc_id), soc_id);
            p.writeInt32(newState);
            appendPrintBuf("%s {%s}", printBuf,
                radioStateToString(CALL_ONSTATEREQUEST(soc_id)));
 break;


 case RIL_UNSOL_NITZ_TIME_RECEIVED:
            p.writeInt64(timeReceived);
 break;
 }

 if (s_callbacks.version < 13) {
 if (shouldScheduleTimeout) {
 UserCallbackInfo *p_info = internalRequestTimedCallback(wakeTimeoutCallback, NULL,
 &TIMEVAL_WAKE_TIMEOUT);

 if (p_info == NULL) {
 goto error_exit;
 } else {
 if (s_last_wake_timeout_info != NULL) {
                    s_last_wake_timeout_info->userParam = (void *)1;
 }
                s_last_wake_timeout_info = p_info;
 }
 }
 }

#if VDBG
    RLOGI("%s UNSOLICITED: %s length:%d", rilSocketIdToString(soc_id), requestToString(unsolResponse), p.dataSize());
#endif
    ret = sendResponse(p, soc_id);
 if (ret != 0 && unsolResponse == RIL_UNSOL_NITZ_TIME_RECEIVED) {


 if (s_lastNITZTimeData != NULL) {
            free (s_lastNITZTimeData);
            s_lastNITZTimeData = NULL;
 }

        s_lastNITZTimeData = calloc(p.dataSize(), 1);
 if (s_lastNITZTimeData == NULL) {
             RLOGE("Memory allocation failed in RIL_onUnsolicitedResponse");
 goto error_exit;
 }
        s_lastNITZTimeDataSize = p.dataSize();
        memcpy(s_lastNITZTimeData, p.data(), p.dataSize());
 }

 return;

error_exit:
 if (shouldScheduleTimeout) {
        releaseWakeLock();
 }
}

