 }
 case IVD_CMD_CTL_FLUSH:
            ret = ihevcd_set_flush_mode(ps_codec_obj, (void *)pv_api_ip,
 (void *)pv_api_op);
 break;
 case IVD_CMD_CTL_GETBUFINFO:
            ret = ihevcd_get_buf_info(ps_codec_obj, (void *)pv_api_ip,
 (void *)pv_api_op);
 break;
 case IVD_CMD_CTL_GETVERSION:
 {
 ivd_ctl_getversioninfo_ip_t *ps_ip;
 ivd_ctl_getversioninfo_op_t *ps_op;
            IV_API_CALL_STATUS_T ret;
            ps_ip = (ivd_ctl_getversioninfo_ip_t *)pv_api_ip;
            ps_op = (ivd_ctl_getversioninfo_op_t *)pv_api_op;

            ps_op->u4_error_code = IV_SUCCESS;

 if((WORD32)ps_ip->u4_version_buffer_size <= 0)
 {
                ps_op->u4_error_code = IHEVCD_CXA_VERS_BUF_INSUFFICIENT;
                ret = IV_FAIL;
 }
 else
 {
                ret = ihevcd_get_version((CHAR *)ps_ip->pv_version_buffer,
                                         ps_ip->u4_version_buffer_size);
 if(ret != IV_SUCCESS)
 {
                    ps_op->u4_error_code = IHEVCD_CXA_VERS_BUF_INSUFFICIENT;
                    ret = IV_FAIL;
 }
 }
 }
 break;
 case IHEVCD_CXA_CMD_CTL_DEGRADE:
            ret = ihevcd_set_degrade(ps_codec_obj, (void *)pv_api_ip,
 (void *)pv_api_op);
 break;
 case IHEVCD_CXA_CMD_CTL_SET_NUM_CORES:
            ret = ihevcd_set_num_cores(ps_codec_obj, (void *)pv_api_ip,
 (void *)pv_api_op);
 break;
 case IHEVCD_CXA_CMD_CTL_GET_BUFFER_DIMENSIONS:
            ret = ihevcd_get_frame_dimensions(ps_codec_obj, (void *)pv_api_ip,
 (void *)pv_api_op);
 break;
 case IHEVCD_CXA_CMD_CTL_GET_VUI_PARAMS:
            ret = ihevcd_get_vui_params(ps_codec_obj, (void *)pv_api_ip,
 (void *)pv_api_op);
 break;
 case IHEVCD_CXA_CMD_CTL_GET_SEI_MASTERING_PARAMS:
            ret = ihevcd_get_sei_mastering_params(ps_codec_obj, (void *)pv_api_ip,
 (void *)pv_api_op);
 break;
 case IHEVCD_CXA_CMD_CTL_SET_PROCESSOR:
            ret = ihevcd_set_processor(ps_codec_obj, (void *)pv_api_ip,
 (void *)pv_api_op);
 break;
 default:
            DEBUG("\nDo nothing\n");
 break;
 }

 return ret;
}

WORD32 ihevcd_get_sei_mastering_params(iv_obj_t *ps_codec_obj,
 void *pv_api_ip,
 void *pv_api_op)
{
 ihevcd_cxa_ctl_get_sei_mastering_params_ip_t *ps_ip;
 ihevcd_cxa_ctl_get_sei_mastering_params_op_t *ps_op;
 codec_t *ps_codec = (codec_t *)ps_codec_obj->pv_codec_handle;
 sei_params_t *ps_sei;
 mastering_dis_col_vol_sei_params_t *ps_mastering_dis_col_vol;
    WORD32 i;

    ps_ip = (ihevcd_cxa_ctl_get_sei_mastering_params_ip_t *)pv_api_ip;
    ps_op = (ihevcd_cxa_ctl_get_sei_mastering_params_op_t *)pv_api_op;
    UNUSED(ps_ip);
 if(NULL == ps_codec->ps_disp_buf)
 {
        ps_op->u4_error_code = IHEVCD_SEI_MASTERING_PARAMS_NOT_FOUND;
 return IV_FAIL;
 }
    ps_sei = &ps_codec->ps_disp_buf->s_sei_params;
 if((0 == ps_sei->i4_sei_mastering_disp_colour_vol_params_present_flags)
 || (0 == ps_sei->i1_sei_parameters_present_flag))
 {
        ps_op->u4_error_code = IHEVCD_SEI_MASTERING_PARAMS_NOT_FOUND;
 return IV_FAIL;
 }

    ps_mastering_dis_col_vol = &ps_sei->s_mastering_dis_col_vol_sei_params;

 for(i = 0; i < 3; i++)
 {
        ps_op->au2_display_primaries_x[i] =
                    ps_mastering_dis_col_vol->au2_display_primaries_x[i];

        ps_op->au2_display_primaries_y[i] =
                    ps_mastering_dis_col_vol->au2_display_primaries_y[i];
 }

    ps_op->u2_white_point_x = ps_mastering_dis_col_vol->u2_white_point_x;

    ps_op->u2_white_point_y = ps_mastering_dis_col_vol->u2_white_point_y;

    ps_op->u4_max_display_mastering_luminance =
                    ps_mastering_dis_col_vol->u4_max_display_mastering_luminance;

    ps_op->u4_min_display_mastering_luminance =
                    ps_mastering_dis_col_vol->u4_min_display_mastering_luminance;

 return IV_SUCCESS;
}

IHEVCD_ERROR_T ihevcd_parse_coding_quadtree(codec_t *ps_codec,
                                            WORD32 x0,
                                            WORD32 y0,
                                            WORD32 log2_cb_size,
                                            WORD32 ct_depth)
{
    IHEVCD_ERROR_T ret = (IHEVCD_ERROR_T)IHEVCD_SUCCESS;
 sps_t *ps_sps;
 pps_t *ps_pps;
    WORD32 split_cu_flag;
    WORD32 x1, y1;
    WORD32 cu_pos_x;
    WORD32 cu_pos_y;
 bitstrm_t *ps_bitstrm = &ps_codec->s_parse.s_bitstrm;
 cab_ctxt_t *ps_cabac = &ps_codec->s_parse.s_cabac;
    WORD32 cb_size = 1 << log2_cb_size;
    ps_sps = ps_codec->s_parse.ps_sps;
    ps_pps = ps_codec->s_parse.ps_pps;

 /* Compute CU position with respect to current CTB in (8x8) units */
    cu_pos_x = (x0 - (ps_codec->s_parse.i4_ctb_x << ps_sps->i1_log2_ctb_size)) >> 3;
    cu_pos_y = (y0 - (ps_codec->s_parse.i4_ctb_y << ps_sps->i1_log2_ctb_size)) >> 3;

    ps_codec->s_parse.s_cu.i4_pos_x = cu_pos_x;
    ps_codec->s_parse.s_cu.i4_pos_y = cu_pos_y;

    ps_codec->s_parse.s_cu.i4_log2_cb_size = log2_cb_size;

    ps_codec->s_parse.i4_ct_depth = ct_depth;
 {
        UWORD32 *pu4_ct_depth_top = ps_codec->s_parse.pu4_ct_depth_top;
        UWORD32 u4_ct_depth_left = ps_codec->s_parse.u4_ct_depth_left;
        UWORD32 u4_ct_depth_top = 0;
        UWORD32 u4_mask;
        UWORD32 u4_top_mask, u4_left_mask;
        WORD32  ctxt_idx;
        UWORD32 u4_min_cu_x = x0 / 8;
        UWORD32 u4_min_cu_y = y0 / 8;

        pu4_ct_depth_top += (u4_min_cu_x / 16);




 if(((x0 + (1 << log2_cb_size)) <= ps_sps->i2_pic_width_in_luma_samples) &&
 ((y0 + (1 << log2_cb_size)) <= ps_sps->i2_pic_height_in_luma_samples) &&
 (log2_cb_size > ps_sps->i1_log2_min_coding_block_size))
 {

            ctxt_idx = IHEVC_CAB_SPLIT_CU_FLAG;
 /* Split cu context increment is decided based on left and top Coding tree
             * depth which is stored at frame level
             */
 /* Check if the CTB is in first row in the current slice or tile */
 if((0 != cu_pos_y) ||
 ((0 != ps_codec->s_parse.i4_ctb_slice_y) &&
 (0 != ps_codec->s_parse.i4_ctb_tile_y)))
 {
                u4_ct_depth_top = *pu4_ct_depth_top;
                u4_ct_depth_top >>= ((u4_min_cu_x % 16) * 2);
                u4_ct_depth_top &= 3;

 if((WORD32)u4_ct_depth_top > ct_depth)
                    ctxt_idx++;
 }

 /* Check if the CTB is in first column in the current slice or tile */
 /*****************************************************************/
 /* If cu_pos_x is non-zero then left is available                */
 /* If cu_pos_x is zero then ensure both the following are true   */
 /*    Current CTB is not the first CTB in a tile row             */
 /*    Current CTB is not the first CTB in a slice                */
 /*****************************************************************/
 if((0 != cu_pos_x) ||
 (((0 != ps_codec->s_parse.i4_ctb_slice_x) || (0 != ps_codec->s_parse.i4_ctb_slice_y)) &&
 (0 != ps_codec->s_parse.i4_ctb_tile_x)))
 {
                u4_ct_depth_left >>= ((u4_min_cu_y % 16) * 2);
                u4_ct_depth_left &= 3;
 if((WORD32)u4_ct_depth_left > ct_depth)
                    ctxt_idx++;
 }
            TRACE_CABAC_CTXT("split_cu_flag", ps_cabac->u4_range, ctxt_idx);
            split_cu_flag = ihevcd_cabac_decode_bin(ps_cabac, ps_bitstrm, ctxt_idx);
            AEV_TRACE("split_cu_flag", split_cu_flag, ps_cabac->u4_range);
 }
 else
 {
 if(log2_cb_size > ps_sps->i1_log2_min_coding_block_size)
                split_cu_flag = 1;
 else
                split_cu_flag = 0;
 }

 if(0 == split_cu_flag)
 {
 /* Update top ct_depth */
            u4_ct_depth_top = *pu4_ct_depth_top;
 /* Since Max cb_size is 64, maximum of 8 bits will be set or reset */
 /* Also since Coding block will be within 64x64 grid, only 8bits within a WORD32
             * need to be updated. These 8 bits will not cross 8 bit boundaries
             */
            u4_mask = DUP_LSB_11(cb_size / 8);

            u4_top_mask = u4_mask << ((u4_min_cu_x % 16) * 2);
            u4_ct_depth_top &= ~u4_top_mask;

 if(ct_depth)
 {
                u4_top_mask = gau4_ct_depth_mask[ct_depth] & u4_mask;

                u4_top_mask = u4_top_mask << ((u4_min_cu_x % 16) * 2);
                u4_ct_depth_top |= u4_top_mask;
 }

 *pu4_ct_depth_top = u4_ct_depth_top;

 /* Update left ct_depth */
            u4_ct_depth_left = ps_codec->s_parse.u4_ct_depth_left;

            u4_left_mask = u4_mask << ((u4_min_cu_y % 16) * 2);

            u4_ct_depth_left &= ~u4_left_mask;
 if(ct_depth)
 {
                u4_left_mask = gau4_ct_depth_mask[ct_depth] & u4_mask;

                u4_left_mask = u4_left_mask << ((u4_min_cu_y % 16) * 2);
                u4_ct_depth_left |= u4_left_mask;
 }

            ps_codec->s_parse.u4_ct_depth_left = u4_ct_depth_left;
 }
 }
 if((ps_pps->i1_cu_qp_delta_enabled_flag) &&
 (log2_cb_size >= ps_pps->i1_log2_min_cu_qp_delta_size))
 {
        ps_codec->s_parse.i4_is_cu_qp_delta_coded = 0;
        ps_codec->s_parse.i4_cu_qp_delta = 0;
 }
 if(split_cu_flag)
 {
        x1 = x0 + ((1 << log2_cb_size) >> 1);
        y1 = y0 + ((1 << log2_cb_size) >> 1);

        ret = ihevcd_parse_coding_quadtree(ps_codec, x0, y0, log2_cb_size - 1, ct_depth + 1);
        RETURN_IF((IHEVCD_ERROR_T)IHEVCD_SUCCESS != ret, ret);

 /* At frame boundaries coding quadtree nodes are sent only if they fall within the frame */
 if(x1 < ps_sps->i2_pic_width_in_luma_samples)
 {
            ret = ihevcd_parse_coding_quadtree(ps_codec, x1, y0, log2_cb_size - 1, ct_depth + 1);
            RETURN_IF((IHEVCD_ERROR_T)IHEVCD_SUCCESS != ret, ret);
 }

 if(y1 < ps_sps->i2_pic_height_in_luma_samples)
 {
            ret = ihevcd_parse_coding_quadtree(ps_codec, x0, y1, log2_cb_size - 1, ct_depth + 1);
            RETURN_IF((IHEVCD_ERROR_T)IHEVCD_SUCCESS != ret, ret);
 }

 if((x1 < ps_sps->i2_pic_width_in_luma_samples) &&
 (y1 < ps_sps->i2_pic_height_in_luma_samples))
 {
            ret = ihevcd_parse_coding_quadtree(ps_codec, x1, y1, log2_cb_size - 1, ct_depth + 1);
            RETURN_IF((IHEVCD_ERROR_T)IHEVCD_SUCCESS != ret, ret);
 }
 }
 else
 {
 /* Set current group QP if current CU is aligned with the group */
 {
            WORD32 cu_pos_x = ps_codec->s_parse.s_cu.i4_pos_x << 3;
            WORD32 cu_pos_y = ps_codec->s_parse.s_cu.i4_pos_y << 3;

            WORD32 qpg_x = (cu_pos_x - (cu_pos_x & ((1 << ps_pps->i1_log2_min_cu_qp_delta_size) - 1)));
            WORD32 qpg_y = (cu_pos_y - (cu_pos_y & ((1 << ps_pps->i1_log2_min_cu_qp_delta_size) - 1)));

 if((cu_pos_x == qpg_x) &&
 (cu_pos_y == qpg_y))
 {
                ps_codec->s_parse.u4_qpg = ps_codec->s_parse.u4_qp;

                ps_codec->s_parse.s_cu.i4_cu_qp_delta = 0;

 }
 }

        ret = ihevcd_parse_coding_unit(ps_codec, x0, y0, log2_cb_size);
        RETURN_IF((IHEVCD_ERROR_T)IHEVCD_SUCCESS != ret, ret);

 if(ps_pps->i1_cu_qp_delta_enabled_flag)
 {
            WORD32 qp_pred, qp_left, qp_top;
            WORD32 cu_pos_x;
            WORD32 cu_pos_y;
            WORD32 qpg_x;
            WORD32 qpg_y;
            WORD32 i, j;
            WORD32 qp;
            WORD32 cur_cu_offset;
 tu_t *ps_tu = ps_codec->s_parse.ps_tu;
            WORD32 cb_size = 1 << ps_codec->s_parse.s_cu.i4_log2_cb_size;

            cu_pos_x = ps_codec->s_parse.s_cu.i4_pos_x << 3;
            cu_pos_y = ps_codec->s_parse.s_cu.i4_pos_y << 3;

            qpg_x = (cu_pos_x - (cu_pos_x & ((1 << ps_pps->i1_log2_min_cu_qp_delta_size) - 1))) >> 3;
            qpg_y = (cu_pos_y - (cu_pos_y & ((1 << ps_pps->i1_log2_min_cu_qp_delta_size) - 1))) >> 3;

 /*previous coded Qp*/
            qp_left = ps_codec->s_parse.u4_qpg;
            qp_top = ps_codec->s_parse.u4_qpg;

 if(qpg_x > 0)
 {
                qp_left = ps_codec->s_parse.ai1_8x8_cu_qp[qpg_x - 1 + (qpg_y * 8)];
 }
 if(qpg_y > 0)
 {
                qp_top = ps_codec->s_parse.ai1_8x8_cu_qp[qpg_x + ((qpg_y - 1) * 8)];
 }

            qp_pred = (qp_left + qp_top + 1) >> 1;
 /* Since qp_pred + ps_codec->s_parse.s_cu.i4_cu_qp_delta can be negative,
            52 is added before taking modulo 52 */
            qp = (qp_pred + ps_codec->s_parse.s_cu.i4_cu_qp_delta + 52) % 52;

            cur_cu_offset = (cu_pos_x >> 3) + cu_pos_y;
 for(i = 0; i < (cb_size >> 3); i++)
 {
 for(j = 0; j < (cb_size >> 3); j++)
 {
                    ps_codec->s_parse.ai1_8x8_cu_qp[cur_cu_offset + (i * 8) + j] = qp;
 }
 }

            ps_codec->s_parse.u4_qp = qp;
            ps_codec->s_parse.s_cu.i4_qp = qp;


 /* When change in QP is signaled, update the QP in TUs that are already parsed in the CU */
 {
 tu_t *ps_tu_tmp;
                ps_tu_tmp = ps_tu - ps_codec->s_parse.s_cu.i4_tu_cnt;
                ps_tu->b7_qp = ps_codec->s_parse.u4_qp;
 while(ps_tu_tmp != ps_tu)
 {
                    ps_tu_tmp->b7_qp = ps_codec->s_parse.u4_qp;

                    ps_tu_tmp++;
 }
 }
 if(ps_codec->s_parse.s_cu.i4_cu_qp_delta)
 {
                WORD32 ctb_indx;
                ctb_indx = ps_codec->s_parse.i4_ctb_x + ps_sps->i2_pic_wd_in_ctb * ps_codec->s_parse.i4_ctb_y;
                ps_codec->s_parse.s_bs_ctxt.pu1_pic_qp_const_in_ctb[ctb_indx >> 3] &= (~(1 << (ctb_indx & 7)));
 }

 }

 }




 return ret;
}

xmlBuildURI(const xmlChar *URI, const xmlChar *base) {
    xmlChar *val = NULL;
 int ret, len, indx, cur, out;
    xmlURIPtr ref = NULL;
    xmlURIPtr bas = NULL;
    xmlURIPtr res = NULL;

 /*
     * 1) The URI reference is parsed into the potential four components and
     *    fragment identifier, as described in Section 4.3.
     *
     *    NOTE that a completely empty URI is treated by modern browsers
     *    as a reference to "." rather than as a synonym for the current
     *    URI.  Should we do that here?
     */
 if (URI == NULL)
	ret = -1;
 else {
 if (*URI) {
	    ref = xmlCreateURI();
 if (ref == NULL)
 goto done;
	    ret = xmlParseURIReference(ref, (const char *) URI);
 }
 else
	    ret = 0;
 }
 if (ret != 0)
 goto done;
 if ((ref != NULL) && (ref->scheme != NULL)) {
 /*
	 * The URI is absolute don't modify.
	 */
	val = xmlStrdup(URI);
 goto done;
 }
 if (base == NULL)
	ret = -1;
 else {
	bas = xmlCreateURI();
 if (bas == NULL)
 goto done;
	ret = xmlParseURIReference(bas, (const char *) base);
 }
 if (ret != 0) {
 if (ref)
	    val = xmlSaveUri(ref);
 goto done;
 }
 if (ref == NULL) {
 /*
	 * the base fragment must be ignored
	 */
 if (bas->fragment != NULL) {
	    xmlFree(bas->fragment);
	    bas->fragment = NULL;
 }
	val = xmlSaveUri(bas);
 goto done;
 }

 /*
     * 2) If the path component is empty and the scheme, authority, and
     *    query components are undefined, then it is a reference to the
     *    current document and we are done.  Otherwise, the reference URI's
     *    query and fragment components are defined as found (or not found)
     *    within the URI reference and not inherited from the base URI.
     *
     *    NOTE that in modern browsers, the parsing differs from the above
     *    in the following aspect:  the query component is allowed to be
     *    defined while still treating this as a reference to the current
     *    document.
     */
    res = xmlCreateURI();
 if (res == NULL)
 goto done;
 if ((ref->scheme == NULL) && (ref->path == NULL) &&
 ((ref->authority == NULL) && (ref->server == NULL))) {
 if (bas->scheme != NULL)
	    res->scheme = xmlMemStrdup(bas->scheme);
 if (bas->authority != NULL)
	    res->authority = xmlMemStrdup(bas->authority);
 else if (bas->server != NULL) {
	    res->server = xmlMemStrdup(bas->server);
 if (bas->user != NULL)
		res->user = xmlMemStrdup(bas->user);
	    res->port = bas->port;
 }
 if (bas->path != NULL)
	    res->path = xmlMemStrdup(bas->path);
 if (ref->query_raw != NULL)
	    res->query_raw = xmlMemStrdup (ref->query_raw);
 else if (ref->query != NULL)
	    res->query = xmlMemStrdup(ref->query);
 else if (bas->query_raw != NULL)
	    res->query_raw = xmlMemStrdup(bas->query_raw);
 else if (bas->query != NULL)
	    res->query = xmlMemStrdup(bas->query);
 if (ref->fragment != NULL)
	    res->fragment = xmlMemStrdup(ref->fragment);
 goto step_7;
 }

 /*
     * 3) If the scheme component is defined, indicating that the reference
     *    starts with a scheme name, then the reference is interpreted as an
     *    absolute URI and we are done.  Otherwise, the reference URI's
     *    scheme is inherited from the base URI's scheme component.
     */
 if (ref->scheme != NULL) {
	val = xmlSaveUri(ref);
 goto done;
 }
 if (bas->scheme != NULL)
	res->scheme = xmlMemStrdup(bas->scheme);

 if (ref->query_raw != NULL)
	res->query_raw = xmlMemStrdup(ref->query_raw);
 else if (ref->query != NULL)
	res->query = xmlMemStrdup(ref->query);
 if (ref->fragment != NULL)
	res->fragment = xmlMemStrdup(ref->fragment);

 /*
     * 4) If the authority component is defined, then the reference is a
     *    network-path and we skip to step 7.  Otherwise, the reference
     *    URI's authority is inherited from the base URI's authority
     *    component, which will also be undefined if the URI scheme does not
     *    use an authority component.
     */
 if ((ref->authority != NULL) || (ref->server != NULL)) {
 if (ref->authority != NULL)
	    res->authority = xmlMemStrdup(ref->authority);
 else {
	    res->server = xmlMemStrdup(ref->server);
 if (ref->user != NULL)
		res->user = xmlMemStrdup(ref->user);
            res->port = ref->port;
 }
 if (ref->path != NULL)
	    res->path = xmlMemStrdup(ref->path);
 goto step_7;
 }
 if (bas->authority != NULL)
	res->authority = xmlMemStrdup(bas->authority);
 else if (bas->server != NULL) {
	res->server = xmlMemStrdup(bas->server);
 if (bas->user != NULL)
	    res->user = xmlMemStrdup(bas->user);
	res->port = bas->port;
 }

 /*
     * 5) If the path component begins with a slash character ("/"), then
     *    the reference is an absolute-path and we skip to step 7.
     */
 if ((ref->path != NULL) && (ref->path[0] == '/')) {
	res->path = xmlMemStrdup(ref->path);
 goto step_7;
 }


 /*
     * 6) If this step is reached, then we are resolving a relative-path
     *    reference.  The relative path needs to be merged with the base
     *    URI's path.  Although there are many ways to do this, we will
     *    describe a simple method using a separate string buffer.
     *
     * Allocate a buffer large enough for the result string.
     */
    len = 2; /* extra / and 0 */
 if (ref->path != NULL)
	len += strlen(ref->path);
 if (bas->path != NULL)
	len += strlen(bas->path);
    res->path = (char *) xmlMallocAtomic(len);
 if (res->path == NULL) {
        xmlURIErrMemory("resolving URI against base\n");
 goto done;
 }
    res->path[0] = 0;

 /*
     * a) All but the last segment of the base URI's path component is
     *    copied to the buffer.  In other words, any characters after the
     *    last (right-most) slash character, if any, are excluded.
     */
    cur = 0;
    out = 0;
 if (bas->path != NULL) {
 while (bas->path[cur] != 0) {
 while ((bas->path[cur] != 0) && (bas->path[cur] != '/'))
		cur++;
 if (bas->path[cur] == 0)
 break;

	    cur++;
 while (out < cur) {
		res->path[out] = bas->path[out];
		out++;
 }
 }
 }
    res->path[out] = 0;

 /*
     * b) The reference's path component is appended to the buffer
     *    string.
     */
 if (ref->path != NULL && ref->path[0] != 0) {
	indx = 0;
 /*
	 * Ensure the path includes a '/'
	 */
 if ((out == 0) && (bas->server != NULL))
	    res->path[out++] = '/';
 while (ref->path[indx] != 0) {
	    res->path[out++] = ref->path[indx++];
 }
 }
    res->path[out] = 0;

 /*
     * Steps c) to h) are really path normalization steps
     */
    xmlNormalizeURIPath(res->path);

step_7:

 /*
     * 7) The resulting URI components, including any inherited from the
     *    base URI, are recombined to give the absolute form of the URI
     *    reference.
     */
    val = xmlSaveUri(res);

done:
 if (ref != NULL)
	xmlFreeURI(ref);
 if (bas != NULL)
	xmlFreeURI(bas);
 if (res != NULL)
	xmlFreeURI(res);
 return(val);
}

xmlCanonicPath(const xmlChar *path)
{
/*
 * For Windows implementations, additional work needs to be done to
 * replace backslashes in pathnames with "forward slashes"
 */
#if defined(_WIN32) && !defined(__CYGWIN__)
 int len = 0;
 int i = 0;
    xmlChar *p = NULL;
#endif
    xmlURIPtr uri;
    xmlChar *ret;
 const xmlChar *absuri;

 if (path == NULL)
 return(NULL);

#if defined(_WIN32)
 /*
     * We must not change the backslashes to slashes if the the path
     * starts with \\?\
     * Those paths can be up to 32k characters long.
     * Was added specifically for OpenOffice, those paths can't be converted
     * to URIs anyway.
     */
 if ((path[0] == '\\') && (path[1] == '\\') && (path[2] == '?') &&
 (path[3] == '\\') )
 return xmlStrdup((const xmlChar *) path);
#endif

 /* sanitize filename starting with // so it can be used as URI */
 if ((path[0] == '/') && (path[1] == '/') && (path[2] != '/'))
        path++;

 if ((uri = xmlParseURI((const char *) path)) != NULL) {
	xmlFreeURI(uri);
 return xmlStrdup(path);
 }

 /* Check if this is an "absolute uri" */
    absuri = xmlStrstr(path, BAD_CAST "://");
 if (absuri != NULL) {
 int l, j;
 unsigned char c;
	xmlChar *escURI;

 /*
	 * this looks like an URI where some parts have not been
	 * escaped leading to a parsing problem.  Check that the first
	 * part matches a protocol.
	 */
	l = absuri - path;
 /* Bypass if first part (part before the '://') is > 20 chars */
 if ((l <= 0) || (l > 20))
 goto path_processing;
 /* Bypass if any non-alpha characters are present in first part */
 for (j = 0;j < l;j++) {
	    c = path[j];
 if (!(((c >= 'a') && (c <= 'z')) || ((c >= 'A') && (c <= 'Z'))))
 goto path_processing;
 }

 /* Escape all except the characters specified in the supplied path */
        escURI = xmlURIEscapeStr(path, BAD_CAST ":/?_.#&;=");
 if (escURI != NULL) {
 /* Try parsing the escaped path */
	    uri = xmlParseURI((const char *) escURI);
 /* If successful, return the escaped string */
 if (uri != NULL) {
	        xmlFreeURI(uri);
 return escURI;
 }
 }
 }

path_processing:
/* For Windows implementations, replace backslashes with 'forward slashes' */
#if defined(_WIN32) && !defined(__CYGWIN__)
 /*
     * Create a URI structure
     */
    uri = xmlCreateURI();
 if (uri == NULL) { /* Guard against 'out of memory' */
 return(NULL);
 }

    len = xmlStrlen(path);
 if ((len > 2) && IS_WINDOWS_PATH(path)) {
 /* make the scheme 'file' */
	uri->scheme = xmlStrdup(BAD_CAST "file");
 /* allocate space for leading '/' + path + string terminator */
	uri->path = xmlMallocAtomic(len + 2);
 if (uri->path == NULL) {
	    xmlFreeURI(uri); /* Guard agains 'out of memory' */
 return(NULL);
 }
 /* Put in leading '/' plus path */
	uri->path[0] = '/';
	p = uri->path + 1;
	strncpy(p, path, len + 1);
 } else {
	uri->path = xmlStrdup(path);
 if (uri->path == NULL) {
	    xmlFreeURI(uri);
 return(NULL);
 }
	p = uri->path;
 }
 /* Now change all occurences of '\' to '/' */
 while (*p != '\0') {
 if (*p == '\\')
 *p = '/';
	p++;
 }

 if (uri->scheme == NULL) {
	ret = xmlStrdup((const xmlChar *) uri->path);
 } else {
	ret = xmlSaveUri(uri);
 }

    xmlFreeURI(uri);
#else
    ret = xmlStrdup((const xmlChar *) path);
#endif
 return(ret);
}

xmlCleanURI(xmlURIPtr uri) {
 if (uri == NULL) return;

 if (uri->scheme != NULL) xmlFree(uri->scheme);
    uri->scheme = NULL;
 if (uri->server != NULL) xmlFree(uri->server);
    uri->server = NULL;
 if (uri->user != NULL) xmlFree(uri->user);
    uri->user = NULL;
 if (uri->path != NULL) xmlFree(uri->path);
    uri->path = NULL;
 if (uri->fragment != NULL) xmlFree(uri->fragment);
    uri->fragment = NULL;
 if (uri->opaque != NULL) xmlFree(uri->opaque);
    uri->opaque = NULL;
 if (uri->authority != NULL) xmlFree(uri->authority);
    uri->authority = NULL;
 if (uri->query != NULL) xmlFree(uri->query);
    uri->query = NULL;
 if (uri->query_raw != NULL) xmlFree(uri->query_raw);
    uri->query_raw = NULL;
}

xmlParse3986PathAbEmpty(xmlURIPtr uri, const char **str)
{
 const char *cur;
 int ret;

    cur = *str;

 while (*cur == '/') {
        cur++;
	ret = xmlParse3986Segment(&cur, 0, 1);
 if (ret != 0) return(ret);
 }
 if (uri != NULL) {
 if (uri->path != NULL) xmlFree(uri->path);
 if (*str != cur) {
 if (uri->cleanup & 2)
                uri->path = STRNDUP(*str, cur - *str);
 else
                uri->path = xmlURIUnescapeString(*str, cur - *str, NULL);
 } else {
            uri->path = NULL;
 }
 }
 *str = cur;
 return (0);
}

xmlParse3986RelativeRef(xmlURIPtr uri, const char *str) {
 int ret;

 if ((*str == '/') && (*(str + 1) == '/')) {
        str += 2;
	ret = xmlParse3986Authority(uri, &str);
 if (ret != 0) return(ret);
	ret = xmlParse3986PathAbEmpty(uri, &str);
 if (ret != 0) return(ret);
 } else if (*str == '/') {
	ret = xmlParse3986PathAbsolute(uri, &str);
 if (ret != 0) return(ret);
 } else if (ISA_PCHAR(str)) {
        ret = xmlParse3986PathNoScheme(uri, &str);
 if (ret != 0) return(ret);
 } else {
 /* path-empty is effectively empty */
 if (uri != NULL) {
 if (uri->path != NULL) xmlFree(uri->path);
	    uri->path = NULL;
 }
 }

 if (*str == '?') {
	str++;
	ret = xmlParse3986Query(uri, &str);
 if (ret != 0) return(ret);
 }
 if (*str == '#') {
	str++;
	ret = xmlParse3986Fragment(uri, &str);
 if (ret != 0) return(ret);
 }
 if (*str != 0) {
	xmlCleanURI(uri);
 return(1);
 }
 return(0);
}

namePop(xmlParserCtxtPtr ctxt)
{
 const xmlChar *ret;

 if ((ctxt == NULL) || (ctxt->nameNr <= 0))
 return (NULL);
    ctxt->nameNr--;
 if (ctxt->nameNr > 0)
        ctxt->name = ctxt->nameTab[ctxt->nameNr - 1];
 else
        ctxt->name = NULL;
    ret = ctxt->nameTab[ctxt->nameNr];
    ctxt->nameTab[ctxt->nameNr] = NULL;
 return (ret);
}

static int spacePop(xmlParserCtxtPtr ctxt) {
 int ret;
 if (ctxt->spaceNr <= 0) return(0);
    ctxt->spaceNr--;
 if (ctxt->spaceNr > 0)
	ctxt->space = &ctxt->spaceTab[ctxt->spaceNr - 1];
 else
        ctxt->space = &ctxt->spaceTab[0];
    ret = ctxt->spaceTab[ctxt->spaceNr];
    ctxt->spaceTab[ctxt->spaceNr] = -1;
 return(ret);
}

xmlCreateIOParserCtxt(xmlSAXHandlerPtr sax, void *user_data,
	xmlInputReadCallback   ioread, xmlInputCloseCallback  ioclose,
 void *ioctx, xmlCharEncoding enc) {
    xmlParserCtxtPtr ctxt;
    xmlParserInputPtr inputStream;
    xmlParserInputBufferPtr buf;

 if (ioread == NULL) return(NULL);

    buf = xmlParserInputBufferCreateIO(ioread, ioclose, ioctx, enc);
 if (buf == NULL) {
 if (ioclose != NULL)
            ioclose(ioctx);
 return (NULL);
 }

    ctxt = xmlNewParserCtxt();
 if (ctxt == NULL) {
	xmlFreeParserInputBuffer(buf);
 return(NULL);
 }
 if (sax != NULL) {
#ifdef LIBXML_SAX1_ENABLED
 if (ctxt->sax != (xmlSAXHandlerPtr) &xmlDefaultSAXHandler)
#endif /* LIBXML_SAX1_ENABLED */
	    xmlFree(ctxt->sax);
	ctxt->sax = (xmlSAXHandlerPtr) xmlMalloc(sizeof(xmlSAXHandler));
 if (ctxt->sax == NULL) {
	    xmlErrMemory(ctxt, NULL);
	    xmlFreeParserCtxt(ctxt);
 return(NULL);
 }
	memset(ctxt->sax, 0, sizeof(xmlSAXHandler));
 if (sax->initialized == XML_SAX2_MAGIC)
	    memcpy(ctxt->sax, sax, sizeof(xmlSAXHandler));
 else
	    memcpy(ctxt->sax, sax, sizeof(xmlSAXHandlerV1));
 if (user_data != NULL)
	    ctxt->userData = user_data;
 }

    inputStream = xmlNewIOInputStream(ctxt, buf, enc);
 if (inputStream == NULL) {
	xmlFreeParserCtxt(ctxt);
 return(NULL);
 }
    inputPush(ctxt, inputStream);

 return(ctxt);
}

xmlCtxtReadIO(xmlParserCtxtPtr ctxt, xmlInputReadCallback ioread,
              xmlInputCloseCallback ioclose, void *ioctx,
 const char *URL,
 const char *encoding, int options)
{
    xmlParserInputBufferPtr input;
    xmlParserInputPtr stream;

 if (ioread == NULL)
 return (NULL);
 if (ctxt == NULL)
 return (NULL);
    xmlInitParser();

    xmlCtxtReset(ctxt);

    input = xmlParserInputBufferCreateIO(ioread, ioclose, ioctx,
                                         XML_CHAR_ENCODING_NONE);
 if (input == NULL) {
 if (ioclose != NULL)
            ioclose(ioctx);
 return (NULL);
 }
    stream = xmlNewIOInputStream(ctxt, input, XML_CHAR_ENCODING_NONE);
 if (stream == NULL) {
        xmlFreeParserInputBuffer(input);
 return (NULL);
 }
    inputPush(ctxt, stream);
 return (xmlDoRead(ctxt, URL, encoding, options, 1));
}

xmlFatalErrMsg(xmlParserCtxtPtr ctxt, xmlParserErrors error,
 const char *msg)
{
 if ((ctxt != NULL) && (ctxt->disableSAX != 0) &&
 (ctxt->instate == XML_PARSER_EOF))
 return;
 if (ctxt != NULL)
	ctxt->errNo = error;
    __xmlRaiseError(NULL, NULL, NULL, ctxt, NULL, XML_FROM_PARSER, error,
                    XML_ERR_FATAL, NULL, 0, NULL, NULL, NULL, 0, 0, "%s", msg);
 if (ctxt != NULL) {
	ctxt->wellFormed = 0;
 if (ctxt->recovery == 0)
	    ctxt->disableSAX = 1;
 }
}

xmlFatalErrMsgStr(xmlParserCtxtPtr ctxt, xmlParserErrors error,
 const char *msg, const xmlChar * val)
{
 if ((ctxt != NULL) && (ctxt->disableSAX != 0) &&
 (ctxt->instate == XML_PARSER_EOF))
 return;
 if (ctxt != NULL)
	ctxt->errNo = error;
    __xmlRaiseError(NULL, NULL, NULL, ctxt, NULL,
                    XML_FROM_PARSER, error, XML_ERR_FATAL,
                    NULL, 0, (const char *) val, NULL, NULL, 0, 0, msg,
                    val);
 if (ctxt != NULL) {
	ctxt->wellFormed = 0;
 if (ctxt->recovery == 0)
	    ctxt->disableSAX = 1;
 }
}

xmlNsErr(xmlParserCtxtPtr ctxt, xmlParserErrors error,
 const char *msg,
 const xmlChar * info1, const xmlChar * info2,
 const xmlChar * info3)
{
 if ((ctxt != NULL) && (ctxt->disableSAX != 0) &&
 (ctxt->instate == XML_PARSER_EOF))
 return;
 if (ctxt != NULL)
	ctxt->errNo = error;
    __xmlRaiseError(NULL, NULL, NULL, ctxt, NULL, XML_FROM_NAMESPACE, error,
                    XML_ERR_ERROR, NULL, 0, (const char *) info1,
 (const char *) info2, (const char *) info3, 0, 0, msg,
                    info1, info2, info3);
 if (ctxt != NULL)
	ctxt->nsWellFormed = 0;
}

xmlParseAttValueComplex(xmlParserCtxtPtr ctxt, int *attlen, int normalize) {
    xmlChar limit = 0;
    xmlChar *buf = NULL;
    xmlChar *rep = NULL;
 size_t len = 0;
 size_t buf_size = 0;
 int c, l, in_space = 0;
    xmlChar *current = NULL;
    xmlEntityPtr ent;

 if (NXT(0) == '"') {
	ctxt->instate = XML_PARSER_ATTRIBUTE_VALUE;
	limit = '"';
        NEXT;
 } else if (NXT(0) == '\'') {
	limit = '\'';
	ctxt->instate = XML_PARSER_ATTRIBUTE_VALUE;
        NEXT;
 } else {
	xmlFatalErr(ctxt, XML_ERR_ATTRIBUTE_NOT_STARTED, NULL);
 return(NULL);
 }

 /*
     * allocate a translation buffer.
     */
    buf_size = XML_PARSER_BUFFER_SIZE;
    buf = (xmlChar *) xmlMallocAtomic(buf_size);
 if (buf == NULL) goto mem_error;

 /*
     * OK loop until we reach one of the ending char or a size limit.
     */
    c = CUR_CHAR(l);
 while (((NXT(0) != limit) && /* checked */
 (IS_CHAR(c)) && (c != '<')) &&
 (ctxt->instate != XML_PARSER_EOF)) {
 /*
         * Impose a reasonable limit on attribute size, unless XML_PARSE_HUGE
         * special option is given
         */
 if ((len > XML_MAX_TEXT_LENGTH) &&
 ((ctxt->options & XML_PARSE_HUGE) == 0)) {
            xmlFatalErrMsg(ctxt, XML_ERR_ATTRIBUTE_NOT_FINISHED,
 "AttValue length too long\n");
 goto mem_error;
 }
 if (c == 0) break;
 if (c == '&') {
	    in_space = 0;
 if (NXT(1) == '#') {
 int val = xmlParseCharRef(ctxt);

 if (val == '&') {
 if (ctxt->replaceEntities) {
 if (len + 10 > buf_size) {
			    growBuffer(buf, 10);
 }
			buf[len++] = '&';
 } else {
 /*
			 * The reparsing will be done in xmlStringGetNodeList()
			 * called by the attribute() function in SAX.c
			 */
 if (len + 10 > buf_size) {
			    growBuffer(buf, 10);
 }
			buf[len++] = '&';
			buf[len++] = '#';
			buf[len++] = '3';
			buf[len++] = '8';
			buf[len++] = ';';
 }
 } else if (val != 0) {
 if (len + 10 > buf_size) {
			growBuffer(buf, 10);
 }
		    len += xmlCopyChar(0, &buf[len], val);
 }
 } else {
		ent = xmlParseEntityRef(ctxt);
		ctxt->nbentities++;
 if (ent != NULL)
		    ctxt->nbentities += ent->owner;
 if ((ent != NULL) &&
 (ent->etype == XML_INTERNAL_PREDEFINED_ENTITY)) {
 if (len + 10 > buf_size) {
			growBuffer(buf, 10);
 }
 if ((ctxt->replaceEntities == 0) &&
 (ent->content[0] == '&')) {
			buf[len++] = '&';
			buf[len++] = '#';
			buf[len++] = '3';
			buf[len++] = '8';
			buf[len++] = ';';
 } else {
			buf[len++] = ent->content[0];
 }
 } else if ((ent != NULL) &&
 (ctxt->replaceEntities != 0)) {
 if (ent->etype != XML_INTERNAL_PREDEFINED_ENTITY) {
 ++ctxt->depth;
			rep = xmlStringDecodeEntities(ctxt, ent->content,
						      XML_SUBSTITUTE_REF,
 0, 0, 0);
 --ctxt->depth;
 if (rep != NULL) {
			    current = rep;
 while (*current != 0) { /* non input consuming */
 if ((*current == 0xD) || (*current == 0xA) ||
 (*current == 0x9)) {
                                    buf[len++] = 0x20;
                                    current++;
 } else
                                    buf[len++] = *current++;
 if (len + 10 > buf_size) {
				    growBuffer(buf, 10);
 }
 }
			    xmlFree(rep);
			    rep = NULL;
 }
 } else {
 if (len + 10 > buf_size) {
			    growBuffer(buf, 10);
 }
 if (ent->content != NULL)
			    buf[len++] = ent->content[0];
 }
 } else if (ent != NULL) {
 int i = xmlStrlen(ent->name);
 const xmlChar *cur = ent->name;

 /*
		     * This may look absurd but is needed to detect
		     * entities problems
		     */
 if ((ent->etype != XML_INTERNAL_PREDEFINED_ENTITY) &&
 (ent->content != NULL) && (ent->checked == 0)) {
 unsigned long oldnbent = ctxt->nbentities;

 ++ctxt->depth;
			rep = xmlStringDecodeEntities(ctxt, ent->content,
						  XML_SUBSTITUTE_REF, 0, 0, 0);
 --ctxt->depth;

			ent->checked = (ctxt->nbentities - oldnbent + 1) * 2;
 if (rep != NULL) {
 if (xmlStrchr(rep, '<'))
			        ent->checked |= 1;
			    xmlFree(rep);
			    rep = NULL;
 }
 }

 /*
		     * Just output the reference
		     */
		    buf[len++] = '&';
 while (len + i + 10 > buf_size) {
			growBuffer(buf, i + 10);
 }
 for (;i > 0;i--)
			buf[len++] = *cur++;
		    buf[len++] = ';';
 }
 }
 } else {
 if ((c == 0x20) || (c == 0xD) || (c == 0xA) || (c == 0x9)) {
 if ((len != 0) || (!normalize)) {
 if ((!normalize) || (!in_space)) {
			COPY_BUF(l,buf,len,0x20);
 while (len + 10 > buf_size) {
			    growBuffer(buf, 10);
 }
 }
		    in_space = 1;
 }
 } else {
	        in_space = 0;
		COPY_BUF(l,buf,len,c);
 if (len + 10 > buf_size) {
		    growBuffer(buf, 10);
 }
 }
	    NEXTL(l);
 }
	GROW;
	c = CUR_CHAR(l);
 }
 if (ctxt->instate == XML_PARSER_EOF)
 goto error;

 if ((in_space) && (normalize)) {
 while ((len > 0) && (buf[len - 1] == 0x20)) len--;
 }
    buf[len] = 0;
 if (RAW == '<') {
	xmlFatalErr(ctxt, XML_ERR_LT_IN_ATTRIBUTE, NULL);
 } else if (RAW != limit) {
 if ((c != 0) && (!IS_CHAR(c))) {
	    xmlFatalErrMsg(ctxt, XML_ERR_INVALID_CHAR,
 "invalid character in attribute value\n");
 } else {
	    xmlFatalErrMsg(ctxt, XML_ERR_ATTRIBUTE_NOT_FINISHED,
 "AttValue: ' expected\n");
 }
 } else
	NEXT;

 /*
     * There we potentially risk an overflow, don't allow attribute value of
     * length more than INT_MAX it is a very reasonnable assumption !
     */
 if (len >= INT_MAX) {
        xmlFatalErrMsg(ctxt, XML_ERR_ATTRIBUTE_NOT_FINISHED,
 "AttValue length too long\n");
 goto mem_error;
 }

 if (attlen != NULL) *attlen = (int) len;
 return(buf);

mem_error:
    xmlErrMemory(ctxt, NULL);
error:
 if (buf != NULL)
        xmlFree(buf);
 if (rep != NULL)
        xmlFree(rep);
 return(NULL);
}

xmlParseAttribute2(xmlParserCtxtPtr ctxt,
 const xmlChar * pref, const xmlChar * elem,
 const xmlChar ** prefix, xmlChar ** value,
 int *len, int *alloc)
{
 const xmlChar *name;
    xmlChar *val, *internal_val = NULL;
 int normalize = 0;

 *value = NULL;
    GROW;
    name = xmlParseQName(ctxt, prefix);
 if (name == NULL) {
        xmlFatalErrMsg(ctxt, XML_ERR_NAME_REQUIRED,
 "error parsing attribute name\n");
 return (NULL);
 }

 /*
     * get the type if needed
     */
 if (ctxt->attsSpecial != NULL) {
 int type;

        type = (int) (long) xmlHashQLookup2(ctxt->attsSpecial,
                                            pref, elem, *prefix, name);
 if (type != 0)
            normalize = 1;
 }

 /*
     * read the value
     */
    SKIP_BLANKS;
 if (RAW == '=') {
        NEXT;
        SKIP_BLANKS;
        val = xmlParseAttValueInternal(ctxt, len, alloc, normalize);
 if (normalize) {
 /*
	     * Sometimes a second normalisation pass for spaces is needed
	     * but that only happens if charrefs or entities refernces
	     * have been used in the attribute value, i.e. the attribute
	     * value have been extracted in an allocated string already.
	     */
 if (*alloc) {
 const xmlChar *val2;

	        val2 = xmlAttrNormalizeSpace2(ctxt, val, len);
 if ((val2 != NULL) && (val2 != val)) {
		    xmlFree(val);
		    val = (xmlChar *) val2;
 }
 }
 }
        ctxt->instate = XML_PARSER_CONTENT;
 } else {
        xmlFatalErrMsgStr(ctxt, XML_ERR_ATTRIBUTE_WITHOUT_VALUE,
 "Specification mandate value for attribute %s\n",
                          name);
 return (NULL);
 }

 if (*prefix == ctxt->str_xml) {
 /*
         * Check that xml:lang conforms to the specification
         * No more registered as an error, just generate a warning now
         * since this was deprecated in XML second edition
         */
 if ((ctxt->pedantic) && (xmlStrEqual(name, BAD_CAST "lang"))) {
            internal_val = xmlStrndup(val, *len);
 if (!xmlCheckLanguageID(internal_val)) {
                xmlWarningMsg(ctxt, XML_WAR_LANG_VALUE,
 "Malformed value for xml:lang : %s\n",
                              internal_val, NULL);
 }
 }

 /*
         * Check that xml:space conforms to the specification
         */
 if (xmlStrEqual(name, BAD_CAST "space")) {
            internal_val = xmlStrndup(val, *len);
 if (xmlStrEqual(internal_val, BAD_CAST "default"))
 *(ctxt->space) = 0;
 else if (xmlStrEqual(internal_val, BAD_CAST "preserve"))
 *(ctxt->space) = 1;
 else {
                xmlWarningMsg(ctxt, XML_WAR_SPACE_VALUE,
 "Invalid value \"%s\" for xml:space : \"default\" or \"preserve\" expected\n",
                              internal_val, NULL);
 }
 }
 if (internal_val) {
            xmlFree(internal_val);
 }
 }

 *value = val;
 return (name);
}

xmlParseAttributeListDecl(xmlParserCtxtPtr ctxt) {
 const xmlChar *elemName;
 const xmlChar *attrName;
    xmlEnumerationPtr tree;

 if (CMP9(CUR_PTR, '<', '!', 'A', 'T', 'T', 'L', 'I', 'S', 'T')) {
	xmlParserInputPtr input = ctxt->input;

	SKIP(9);
 if (!IS_BLANK_CH(CUR)) {
	    xmlFatalErrMsg(ctxt, XML_ERR_SPACE_REQUIRED,
 "Space required after '<!ATTLIST'\n");
 }
        SKIP_BLANKS;
        elemName = xmlParseName(ctxt);
 if (elemName == NULL) {
	    xmlFatalErrMsg(ctxt, XML_ERR_NAME_REQUIRED,
 "ATTLIST: no name for Element\n");
 return;
 }
	SKIP_BLANKS;
	GROW;
 while ((RAW != '>') && (ctxt->instate != XML_PARSER_EOF)) {
 const xmlChar *check = CUR_PTR;
 int type;
 int def;
	    xmlChar *defaultValue = NULL;

	    GROW;
            tree = NULL;
	    attrName = xmlParseName(ctxt);
 if (attrName == NULL) {
		xmlFatalErrMsg(ctxt, XML_ERR_NAME_REQUIRED,
 "ATTLIST: no name for Attribute\n");
 break;
 }
	    GROW;
 if (!IS_BLANK_CH(CUR)) {
		xmlFatalErrMsg(ctxt, XML_ERR_SPACE_REQUIRED,
 "Space required after the attribute name\n");
 break;
 }
	    SKIP_BLANKS;

	    type = xmlParseAttributeType(ctxt, &tree);
 if (type <= 0) {
 break;
 }

	    GROW;
 if (!IS_BLANK_CH(CUR)) {
		xmlFatalErrMsg(ctxt, XML_ERR_SPACE_REQUIRED,
 "Space required after the attribute type\n");
 if (tree != NULL)
		    xmlFreeEnumeration(tree);
 break;
 }
	    SKIP_BLANKS;

	    def = xmlParseDefaultDecl(ctxt, &defaultValue);
 if (def <= 0) {
 if (defaultValue != NULL)
		    xmlFree(defaultValue);
 if (tree != NULL)
		    xmlFreeEnumeration(tree);
 break;
 }
 if ((type != XML_ATTRIBUTE_CDATA) && (defaultValue != NULL))
	        xmlAttrNormalizeSpace(defaultValue, defaultValue);

	    GROW;
 if (RAW != '>') {
 if (!IS_BLANK_CH(CUR)) {
		    xmlFatalErrMsg(ctxt, XML_ERR_SPACE_REQUIRED,
 "Space required after the attribute default value\n");
 if (defaultValue != NULL)
			xmlFree(defaultValue);
 if (tree != NULL)
			xmlFreeEnumeration(tree);
 break;
 }
		SKIP_BLANKS;
 }
 if (check == CUR_PTR) {
		xmlFatalErr(ctxt, XML_ERR_INTERNAL_ERROR,
 "in xmlParseAttributeListDecl\n");
 if (defaultValue != NULL)
		    xmlFree(defaultValue);
 if (tree != NULL)
		    xmlFreeEnumeration(tree);
 break;
 }
 if ((ctxt->sax != NULL) && (!ctxt->disableSAX) &&
 (ctxt->sax->attributeDecl != NULL))
		ctxt->sax->attributeDecl(ctxt->userData, elemName, attrName,
	                        type, def, defaultValue, tree);
 else if (tree != NULL)
		xmlFreeEnumeration(tree);

 if ((ctxt->sax2) && (defaultValue != NULL) &&
 (def != XML_ATTRIBUTE_IMPLIED) &&
 (def != XML_ATTRIBUTE_REQUIRED)) {
		xmlAddDefAttrs(ctxt, elemName, attrName, defaultValue);
 }
 if (ctxt->sax2) {
		xmlAddSpecialAttr(ctxt, elemName, attrName, type);
 }
 if (defaultValue != NULL)
	        xmlFree(defaultValue);
	    GROW;
 }
 if (RAW == '>') {
 if (input != ctxt->input) {
		xmlValidityError(ctxt, XML_ERR_ENTITY_BOUNDARY,
 "Attribute list declaration doesn't start and stop in the same entity\n",
                                 NULL, NULL);
 }
	    NEXT;
 }
 }
}

xmlParseConditionalSections(xmlParserCtxtPtr ctxt) {
 int id = ctxt->input->id;

    SKIP(3);
    SKIP_BLANKS;
 if (CMP7(CUR_PTR, 'I', 'N', 'C', 'L', 'U', 'D', 'E')) {
	SKIP(7);
	SKIP_BLANKS;
 if (RAW != '[') {
	    xmlFatalErr(ctxt, XML_ERR_CONDSEC_INVALID, NULL);
	    xmlHaltParser(ctxt);
 return;
 } else {
 if (ctxt->input->id != id) {
		xmlValidityError(ctxt, XML_ERR_ENTITY_BOUNDARY,
 "All markup of the conditional section is not in the same entity\n",
				     NULL, NULL);
 }
	    NEXT;
 }
 if (xmlParserDebugEntities) {
 if ((ctxt->input != NULL) && (ctxt->input->filename))
		xmlGenericError(xmlGenericErrorContext,
 "%s(%d): ", ctxt->input->filename,
			ctxt->input->line);
	    xmlGenericError(xmlGenericErrorContext,
 "Entering INCLUDE Conditional Section\n");
 }

 while (((RAW != 0) && ((RAW != ']') || (NXT(1) != ']') ||
 (NXT(2) != '>'))) && (ctxt->instate != XML_PARSER_EOF)) {
 const xmlChar *check = CUR_PTR;
 unsigned int cons = ctxt->input->consumed;

 if ((RAW == '<') && (NXT(1) == '!') && (NXT(2) == '[')) {
		xmlParseConditionalSections(ctxt);
 } else if (IS_BLANK_CH(CUR)) {
		NEXT;
 } else if (RAW == '%') {
		xmlParsePEReference(ctxt);
 } else
		xmlParseMarkupDecl(ctxt);

 /*
	     * Pop-up of finished entities.
	     */
 while ((RAW == 0) && (ctxt->inputNr > 1))
		xmlPopInput(ctxt);

 if ((CUR_PTR == check) && (cons == ctxt->input->consumed)) {
		xmlFatalErr(ctxt, XML_ERR_EXT_SUBSET_NOT_FINISHED, NULL);
		xmlHaltParser(ctxt);
 break;
 }
 }
 if (xmlParserDebugEntities) {
 if ((ctxt->input != NULL) && (ctxt->input->filename))
		xmlGenericError(xmlGenericErrorContext,
 "%s(%d): ", ctxt->input->filename,
			ctxt->input->line);
	    xmlGenericError(xmlGenericErrorContext,
 "Leaving INCLUDE Conditional Section\n");
 }

 } else if (CMP6(CUR_PTR, 'I', 'G', 'N', 'O', 'R', 'E')) {
 int state;
	xmlParserInputState instate;
 int depth = 0;

	SKIP(6);
	SKIP_BLANKS;
 if (RAW != '[') {
	    xmlFatalErr(ctxt, XML_ERR_CONDSEC_INVALID, NULL);
	    xmlHaltParser(ctxt);
 return;
 } else {
 if (ctxt->input->id != id) {
		xmlValidityError(ctxt, XML_ERR_ENTITY_BOUNDARY,
 "All markup of the conditional section is not in the same entity\n",
				     NULL, NULL);
 }
	    NEXT;
 }
 if (xmlParserDebugEntities) {
 if ((ctxt->input != NULL) && (ctxt->input->filename))
		xmlGenericError(xmlGenericErrorContext,
 "%s(%d): ", ctxt->input->filename,
			ctxt->input->line);
	    xmlGenericError(xmlGenericErrorContext,
 "Entering IGNORE Conditional Section\n");
 }

 /*
	 * Parse up to the end of the conditional section
	 * But disable SAX event generating DTD building in the meantime
	 */
	state = ctxt->disableSAX;
	instate = ctxt->instate;
 if (ctxt->recovery == 0) ctxt->disableSAX = 1;
	ctxt->instate = XML_PARSER_IGNORE;

 while (((depth >= 0) && (RAW != 0)) &&
 (ctxt->instate != XML_PARSER_EOF)) {
 if ((RAW == '<') && (NXT(1) == '!') && (NXT(2) == '[')) {
	    depth++;
	    SKIP(3);
 continue;
 }
 if ((RAW == ']') && (NXT(1) == ']') && (NXT(2) == '>')) {
 if (--depth >= 0) SKIP(3);
 continue;
 }
	  NEXT;
 continue;
 }

	ctxt->disableSAX = state;
	ctxt->instate = instate;

 if (xmlParserDebugEntities) {
 if ((ctxt->input != NULL) && (ctxt->input->filename))
		xmlGenericError(xmlGenericErrorContext,
 "%s(%d): ", ctxt->input->filename,
			ctxt->input->line);
	    xmlGenericError(xmlGenericErrorContext,
 "Leaving IGNORE Conditional Section\n");
 }

 } else {
	xmlFatalErr(ctxt, XML_ERR_CONDSEC_INVALID_KEYWORD, NULL);
	xmlHaltParser(ctxt);
 return;
 }

 if (RAW == 0)
        SHRINK;

 if (RAW == 0) {
	xmlFatalErr(ctxt, XML_ERR_CONDSEC_NOT_FINISHED, NULL);
 } else {
 if (ctxt->input->id != id) {
	    xmlValidityError(ctxt, XML_ERR_ENTITY_BOUNDARY,
 "All markup of the conditional section is not in the same entity\n",
				 NULL, NULL);
 }
 if ((ctxt-> instate != XML_PARSER_EOF) &&
 ((ctxt->input->cur + 3) <= ctxt->input->end))
	    SKIP(3);
 }
}

xmlParseContent(xmlParserCtxtPtr ctxt) {
    GROW;
 while ((RAW != 0) &&
 ((RAW != '<') || (NXT(1) != '/')) &&
 (ctxt->instate != XML_PARSER_EOF)) {
 const xmlChar *test = CUR_PTR;
 unsigned int cons = ctxt->input->consumed;
 const xmlChar *cur = ctxt->input->cur;

 /*
	 * First case : a Processing Instruction.
	 */
 if ((*cur == '<') && (cur[1] == '?')) {
	    xmlParsePI(ctxt);
 }

 /*
	 * Second case : a CDSection
	 */
 /* 2.6.0 test was *cur not RAW */
 else if (CMP9(CUR_PTR, '<', '!', '[', 'C', 'D', 'A', 'T', 'A', '[')) {
	    xmlParseCDSect(ctxt);
 }

 /*
	 * Third case :  a comment
	 */
 else if ((*cur == '<') && (NXT(1) == '!') &&
 (NXT(2) == '-') && (NXT(3) == '-')) {
	    xmlParseComment(ctxt);
	    ctxt->instate = XML_PARSER_CONTENT;
 }

 /*
	 * Fourth case :  a sub-element.
	 */
 else if (*cur == '<') {
	    xmlParseElement(ctxt);
 }

 /*
	 * Fifth case : a reference. If if has not been resolved,
	 *    parsing returns it's Name, create the node
	 */

 else if (*cur == '&') {
	    xmlParseReference(ctxt);
 }

 /*
	 * Last case, text. Note that References are handled directly.
	 */
 else {
	    xmlParseCharData(ctxt, 0);
 }

	GROW;
 /*
	 * Pop-up of finished entities.
	 */
 while ((RAW == 0) && (ctxt->inputNr > 1))
	    xmlPopInput(ctxt);
	SHRINK;

 if ((cons == ctxt->input->consumed) && (test == CUR_PTR)) {
	    xmlFatalErr(ctxt, XML_ERR_INTERNAL_ERROR,
 "detected an error in element content\n");
	    xmlHaltParser(ctxt);
 break;
 }
 }
}

xmlParseElement(xmlParserCtxtPtr ctxt) {
 const xmlChar *name;
 const xmlChar *prefix = NULL;
 const xmlChar *URI = NULL;
    xmlParserNodeInfo node_info;
 int line, tlen = 0;
    xmlNodePtr ret;
 int nsNr = ctxt->nsNr;

 if (((unsigned int) ctxt->nameNr > xmlParserMaxDepth) &&
 ((ctxt->options & XML_PARSE_HUGE) == 0)) {
	xmlFatalErrMsgInt(ctxt, XML_ERR_INTERNAL_ERROR,
 "Excessive depth in document: %d use XML_PARSE_HUGE option\n",
			  xmlParserMaxDepth);
	xmlHaltParser(ctxt);
 return;
 }

 /* Capture start position */
 if (ctxt->record_info) {
        node_info.begin_pos = ctxt->input->consumed +
 (CUR_PTR - ctxt->input->base);
	node_info.begin_line = ctxt->input->line;
 }

 if (ctxt->spaceNr == 0)
	spacePush(ctxt, -1);
 else if (*ctxt->space == -2)
	spacePush(ctxt, -1);
 else
	spacePush(ctxt, *ctxt->space);

    line = ctxt->input->line;
#ifdef LIBXML_SAX1_ENABLED
 if (ctxt->sax2)
#endif /* LIBXML_SAX1_ENABLED */
        name = xmlParseStartTag2(ctxt, &prefix, &URI, &tlen);
#ifdef LIBXML_SAX1_ENABLED
 else
	name = xmlParseStartTag(ctxt);
#endif /* LIBXML_SAX1_ENABLED */
 if (ctxt->instate == XML_PARSER_EOF)
 return;
 if (name == NULL) {
	spacePop(ctxt);
 return;
 }
    namePush(ctxt, name);
    ret = ctxt->node;

#ifdef LIBXML_VALID_ENABLED
 /*
     * [ VC: Root Element Type ]
     * The Name in the document type declaration must match the element
     * type of the root element.
     */
 if (ctxt->validate && ctxt->wellFormed && ctxt->myDoc &&
        ctxt->node && (ctxt->node == ctxt->myDoc->children))
        ctxt->valid &= xmlValidateRoot(&ctxt->vctxt, ctxt->myDoc);
#endif /* LIBXML_VALID_ENABLED */

 /*
     * Check for an Empty Element.
     */
 if ((RAW == '/') && (NXT(1) == '>')) {
        SKIP(2);
 if (ctxt->sax2) {
 if ((ctxt->sax != NULL) && (ctxt->sax->endElementNs != NULL) &&
 (!ctxt->disableSAX))
		ctxt->sax->endElementNs(ctxt->userData, name, prefix, URI);
#ifdef LIBXML_SAX1_ENABLED
 } else {
 if ((ctxt->sax != NULL) && (ctxt->sax->endElement != NULL) &&
 (!ctxt->disableSAX))
		ctxt->sax->endElement(ctxt->userData, name);
#endif /* LIBXML_SAX1_ENABLED */
 }
	namePop(ctxt);
	spacePop(ctxt);
 if (nsNr != ctxt->nsNr)
	    nsPop(ctxt, ctxt->nsNr - nsNr);
 if ( ret != NULL && ctxt->record_info ) {
	   node_info.end_pos = ctxt->input->consumed +
 (CUR_PTR - ctxt->input->base);
	   node_info.end_line = ctxt->input->line;
	   node_info.node = ret;
	   xmlParserAddNodeInfo(ctxt, &node_info);
 }
 return;
 }
 if (RAW == '>') {
        NEXT1;
 } else {
        xmlFatalErrMsgStrIntStr(ctxt, XML_ERR_GT_REQUIRED,
 "Couldn't find end of Start Tag %s line %d\n",
		                name, line, NULL);

 /*
	 * end of parsing of this node.
	 */
	nodePop(ctxt);
	namePop(ctxt);
	spacePop(ctxt);
 if (nsNr != ctxt->nsNr)
	    nsPop(ctxt, ctxt->nsNr - nsNr);

 /*
	 * Capture end position and add node
	 */
 if ( ret != NULL && ctxt->record_info ) {
	   node_info.end_pos = ctxt->input->consumed +
 (CUR_PTR - ctxt->input->base);
	   node_info.end_line = ctxt->input->line;
	   node_info.node = ret;
	   xmlParserAddNodeInfo(ctxt, &node_info);
 }
 return;
 }

 /*
     * Parse the content of the element:
     */
    xmlParseContent(ctxt);
 if (ctxt->instate == XML_PARSER_EOF)
 return;
 if (!IS_BYTE_CHAR(RAW)) {
        xmlFatalErrMsgStrIntStr(ctxt, XML_ERR_TAG_NOT_FINISHED,
 "Premature end of data in tag %s line %d\n",
		                name, line, NULL);

 /*
	 * end of parsing of this node.
	 */
	nodePop(ctxt);
	namePop(ctxt);
	spacePop(ctxt);
 if (nsNr != ctxt->nsNr)
	    nsPop(ctxt, ctxt->nsNr - nsNr);
 return;
 }

 /*
     * parse the end of tag: '</' should be here.
     */
 if (ctxt->sax2) {
	xmlParseEndTag2(ctxt, prefix, URI, line, ctxt->nsNr - nsNr, tlen);
	namePop(ctxt);
 }
#ifdef LIBXML_SAX1_ENABLED
 else
	xmlParseEndTag1(ctxt, line);
#endif /* LIBXML_SAX1_ENABLED */

 /*
     * Capture end position and add node
     */
 if ( ret != NULL && ctxt->record_info ) {
       node_info.end_pos = ctxt->input->consumed +
 (CUR_PTR - ctxt->input->base);
       node_info.end_line = ctxt->input->line;
       node_info.node = ret;
       xmlParserAddNodeInfo(ctxt, &node_info);
 }
}

xmlParseEntityDecl(xmlParserCtxtPtr ctxt) {
 const xmlChar *name = NULL;
    xmlChar *value = NULL;
    xmlChar *URI = NULL, *literal = NULL;
 const xmlChar *ndata = NULL;
 int isParameter = 0;
    xmlChar *orig = NULL;
 int skipped;

 /* GROW; done in the caller */
 if (CMP8(CUR_PTR, '<', '!', 'E', 'N', 'T', 'I', 'T', 'Y')) {
	xmlParserInputPtr input = ctxt->input;
	SHRINK;
	SKIP(8);
	skipped = SKIP_BLANKS;
 if (skipped == 0) {
	    xmlFatalErrMsg(ctxt, XML_ERR_SPACE_REQUIRED,
 "Space required after '<!ENTITY'\n");
 }

 if (RAW == '%') {
	    NEXT;
	    skipped = SKIP_BLANKS;
 if (skipped == 0) {
		xmlFatalErrMsg(ctxt, XML_ERR_SPACE_REQUIRED,
 "Space required after '%%'\n");
 }
	    isParameter = 1;
 }

        name = xmlParseName(ctxt);
 if (name == NULL) {
	    xmlFatalErrMsg(ctxt, XML_ERR_NAME_REQUIRED,
 "xmlParseEntityDecl: no name\n");
 return;
 }
 if (xmlStrchr(name, ':') != NULL) {
	    xmlNsErr(ctxt, XML_NS_ERR_COLON,
 "colons are forbidden from entities names '%s'\n",
		     name, NULL, NULL);
 }
        skipped = SKIP_BLANKS;
 if (skipped == 0) {
	    xmlFatalErrMsg(ctxt, XML_ERR_SPACE_REQUIRED,
 "Space required after the entity name\n");
 }

	ctxt->instate = XML_PARSER_ENTITY_DECL;
 /*
	 * handle the various case of definitions...
	 */
 if (isParameter) {
 if ((RAW == '"') || (RAW == '\'')) {
	        value = xmlParseEntityValue(ctxt, &orig);
 if (value) {
 if ((ctxt->sax != NULL) &&
 (!ctxt->disableSAX) && (ctxt->sax->entityDecl != NULL))
			ctxt->sax->entityDecl(ctxt->userData, name,
		                    XML_INTERNAL_PARAMETER_ENTITY,
				    NULL, NULL, value);
 }
 } else {
	        URI = xmlParseExternalID(ctxt, &literal, 1);
 if ((URI == NULL) && (literal == NULL)) {
		    xmlFatalErr(ctxt, XML_ERR_VALUE_REQUIRED, NULL);
 }
 if (URI) {
		    xmlURIPtr uri;

		    uri = xmlParseURI((const char *) URI);
 if (uri == NULL) {
		        xmlErrMsgStr(ctxt, XML_ERR_INVALID_URI,
 "Invalid URI: %s\n", URI);
 /*
			 * This really ought to be a well formedness error
			 * but the XML Core WG decided otherwise c.f. issue
			 * E26 of the XML erratas.
			 */
 } else {
 if (uri->fragment != NULL) {
 /*
			     * Okay this is foolish to block those but not
			     * invalid URIs.
			     */
			    xmlFatalErr(ctxt, XML_ERR_URI_FRAGMENT, NULL);
 } else {
 if ((ctxt->sax != NULL) &&
 (!ctxt->disableSAX) &&
 (ctxt->sax->entityDecl != NULL))
				ctxt->sax->entityDecl(ctxt->userData, name,
					    XML_EXTERNAL_PARAMETER_ENTITY,
					    literal, URI, NULL);
 }
			xmlFreeURI(uri);
 }
 }
 }
 } else {
 if ((RAW == '"') || (RAW == '\'')) {
	        value = xmlParseEntityValue(ctxt, &orig);
 if ((ctxt->sax != NULL) &&
 (!ctxt->disableSAX) && (ctxt->sax->entityDecl != NULL))
		    ctxt->sax->entityDecl(ctxt->userData, name,
				XML_INTERNAL_GENERAL_ENTITY,
				NULL, NULL, value);
 /*
		 * For expat compatibility in SAX mode.
		 */
 if ((ctxt->myDoc == NULL) ||
 (xmlStrEqual(ctxt->myDoc->version, SAX_COMPAT_MODE))) {
 if (ctxt->myDoc == NULL) {
			ctxt->myDoc = xmlNewDoc(SAX_COMPAT_MODE);
 if (ctxt->myDoc == NULL) {
			    xmlErrMemory(ctxt, "New Doc failed");
 return;
 }
			ctxt->myDoc->properties = XML_DOC_INTERNAL;
 }
 if (ctxt->myDoc->intSubset == NULL)
			ctxt->myDoc->intSubset = xmlNewDtd(ctxt->myDoc,
					    BAD_CAST "fake", NULL, NULL);

		    xmlSAX2EntityDecl(ctxt, name, XML_INTERNAL_GENERAL_ENTITY,
			              NULL, NULL, value);
 }
 } else {
	        URI = xmlParseExternalID(ctxt, &literal, 1);
 if ((URI == NULL) && (literal == NULL)) {
		    xmlFatalErr(ctxt, XML_ERR_VALUE_REQUIRED, NULL);
 }
 if (URI) {
		    xmlURIPtr uri;

		    uri = xmlParseURI((const char *)URI);
 if (uri == NULL) {
		        xmlErrMsgStr(ctxt, XML_ERR_INVALID_URI,
 "Invalid URI: %s\n", URI);
 /*
			 * This really ought to be a well formedness error
			 * but the XML Core WG decided otherwise c.f. issue
			 * E26 of the XML erratas.
			 */
 } else {
 if (uri->fragment != NULL) {
 /*
			     * Okay this is foolish to block those but not
			     * invalid URIs.
			     */
			    xmlFatalErr(ctxt, XML_ERR_URI_FRAGMENT, NULL);
 }
			xmlFreeURI(uri);
 }
 }
 if ((RAW != '>') && (!IS_BLANK_CH(CUR))) {
		    xmlFatalErrMsg(ctxt, XML_ERR_SPACE_REQUIRED,
 "Space required before 'NDATA'\n");
 }
		SKIP_BLANKS;
 if (CMP5(CUR_PTR, 'N', 'D', 'A', 'T', 'A')) {
		    SKIP(5);
 if (!IS_BLANK_CH(CUR)) {
			xmlFatalErrMsg(ctxt, XML_ERR_SPACE_REQUIRED,
 "Space required after 'NDATA'\n");
 }
		    SKIP_BLANKS;
		    ndata = xmlParseName(ctxt);
 if ((ctxt->sax != NULL) && (!ctxt->disableSAX) &&
 (ctxt->sax->unparsedEntityDecl != NULL))
			ctxt->sax->unparsedEntityDecl(ctxt->userData, name,
				    literal, URI, ndata);
 } else {
 if ((ctxt->sax != NULL) &&
 (!ctxt->disableSAX) && (ctxt->sax->entityDecl != NULL))
			ctxt->sax->entityDecl(ctxt->userData, name,
				    XML_EXTERNAL_GENERAL_PARSED_ENTITY,
				    literal, URI, NULL);
 /*
		     * For expat compatibility in SAX mode.
		     * assuming the entity repalcement was asked for
		     */
 if ((ctxt->replaceEntities != 0) &&
 ((ctxt->myDoc == NULL) ||
 (xmlStrEqual(ctxt->myDoc->version, SAX_COMPAT_MODE)))) {
 if (ctxt->myDoc == NULL) {
			    ctxt->myDoc = xmlNewDoc(SAX_COMPAT_MODE);
 if (ctxt->myDoc == NULL) {
			        xmlErrMemory(ctxt, "New Doc failed");
 return;
 }
			    ctxt->myDoc->properties = XML_DOC_INTERNAL;
 }

 if (ctxt->myDoc->intSubset == NULL)
			    ctxt->myDoc->intSubset = xmlNewDtd(ctxt->myDoc,
						BAD_CAST "fake", NULL, NULL);
			xmlSAX2EntityDecl(ctxt, name,
				          XML_EXTERNAL_GENERAL_PARSED_ENTITY,
				          literal, URI, NULL);
 }
 }
 }
 }
 if (ctxt->instate == XML_PARSER_EOF)
 return;
	SKIP_BLANKS;
 if (RAW != '>') {
	    xmlFatalErrMsgStr(ctxt, XML_ERR_ENTITY_NOT_FINISHED,
 "xmlParseEntityDecl: entity %s not terminated\n", name);
	    xmlHaltParser(ctxt);
 } else {
 if (input != ctxt->input) {
		xmlFatalErrMsg(ctxt, XML_ERR_ENTITY_BOUNDARY,
 "Entity declaration doesn't start and stop in the same entity\n");
 }
	    NEXT;
 }
 if (orig != NULL) {
 /*
	     * Ugly mechanism to save the raw entity value.
	     */
	    xmlEntityPtr cur = NULL;

 if (isParameter) {
 if ((ctxt->sax != NULL) &&
 (ctxt->sax->getParameterEntity != NULL))
		    cur = ctxt->sax->getParameterEntity(ctxt->userData, name);
 } else {
 if ((ctxt->sax != NULL) &&
 (ctxt->sax->getEntity != NULL))
		    cur = ctxt->sax->getEntity(ctxt->userData, name);
 if ((cur == NULL) && (ctxt->userData==ctxt)) {
		    cur = xmlSAX2GetEntity(ctxt, name);
 }
 }
 if (cur != NULL) {
 if (cur->orig != NULL)
		    xmlFree(orig);
 else
		    cur->orig = orig;
 } else
		xmlFree(orig);
 }
 if (value != NULL) xmlFree(value);
 if (URI != NULL) xmlFree(URI);
 if (literal != NULL) xmlFree(literal);
 }
}

xmlParseEntityValue(xmlParserCtxtPtr ctxt, xmlChar **orig) {
    xmlChar *buf = NULL;
 int len = 0;
 int size = XML_PARSER_BUFFER_SIZE;
 int c, l;
    xmlChar stop;
    xmlChar *ret = NULL;
 const xmlChar *cur = NULL;
    xmlParserInputPtr input;

 if (RAW == '"') stop = '"';
 else if (RAW == '\'') stop = '\'';
 else {
	xmlFatalErr(ctxt, XML_ERR_ENTITY_NOT_STARTED, NULL);
 return(NULL);
 }
    buf = (xmlChar *) xmlMallocAtomic(size * sizeof(xmlChar));
 if (buf == NULL) {
	xmlErrMemory(ctxt, NULL);
 return(NULL);
 }

 /*
     * The content of the entity definition is copied in a buffer.
     */

    ctxt->instate = XML_PARSER_ENTITY_VALUE;
    input = ctxt->input;
    GROW;
 if (ctxt->instate == XML_PARSER_EOF) {
        xmlFree(buf);
 return(NULL);
 }
    NEXT;
    c = CUR_CHAR(l);
 /*
     * NOTE: 4.4.5 Included in Literal
     * When a parameter entity reference appears in a literal entity
     * value, ... a single or double quote character in the replacement
     * text is always treated as a normal data character and will not
     * terminate the literal.
     * In practice it means we stop the loop only when back at parsing
     * the initial entity and the quote is found
     */
 while (((IS_CHAR(c)) && ((c != stop) || /* checked */
 (ctxt->input != input))) && (ctxt->instate != XML_PARSER_EOF)) {
 if (len + 5 >= size) {
	    xmlChar *tmp;

	    size *= 2;
	    tmp = (xmlChar *) xmlRealloc(buf, size * sizeof(xmlChar));
 if (tmp == NULL) {
		xmlErrMemory(ctxt, NULL);
		xmlFree(buf);
 return(NULL);
 }
	    buf = tmp;
 }
	COPY_BUF(l,buf,len,c);
	NEXTL(l);
 /*
	 * Pop-up of finished entities.
	 */
 while ((RAW == 0) && (ctxt->inputNr > 1)) /* non input consuming */
	    xmlPopInput(ctxt);

	GROW;
	c = CUR_CHAR(l);
 if (c == 0) {
	    GROW;
	    c = CUR_CHAR(l);
 }
 }
    buf[len] = 0;
 if (ctxt->instate == XML_PARSER_EOF) {
        xmlFree(buf);
 return(NULL);
 }

 /*
     * Raise problem w.r.t. '&' and '%' being used in non-entities
     * reference constructs. Note Charref will be handled in
     * xmlStringDecodeEntities()
     */
    cur = buf;
 while (*cur != 0) { /* non input consuming */
 if ((*cur == '%') || ((*cur == '&') && (cur[1] != '#'))) {
	    xmlChar *name;
	    xmlChar tmp = *cur;

	    cur++;
	    name = xmlParseStringName(ctxt, &cur);
 if ((name == NULL) || (*cur != ';')) {
		xmlFatalErrMsgInt(ctxt, XML_ERR_ENTITY_CHAR_ERROR,
 "EntityValue: '%c' forbidden except for entities references\n",
	                          tmp);
 }
 if ((tmp == '%') && (ctxt->inSubset == 1) &&
 (ctxt->inputNr == 1)) {
		xmlFatalErr(ctxt, XML_ERR_ENTITY_PE_INTERNAL, NULL);
 }
 if (name != NULL)
		xmlFree(name);
 if (*cur == 0)
 break;
 }
	cur++;
 }

 /*
     * Then PEReference entities are substituted.
     */
 if (c != stop) {
	xmlFatalErr(ctxt, XML_ERR_ENTITY_NOT_FINISHED, NULL);
	xmlFree(buf);
 } else {
	NEXT;
 /*
	 * NOTE: 4.4.7 Bypassed
	 * When a general entity reference appears in the EntityValue in
	 * an entity declaration, it is bypassed and left as is.
	 * so XML_SUBSTITUTE_REF is not set here.
	 */
 ++ctxt->depth;
	ret = xmlStringDecodeEntities(ctxt, buf, XML_SUBSTITUTE_PEREF,
 0, 0, 0);
 --ctxt->depth;
 if (orig != NULL)
 *orig = buf;
 else
	    xmlFree(buf);
 }

 return(ret);
}

xmlParseExternalEntityPrivate(xmlDocPtr doc, xmlParserCtxtPtr oldctxt,
	              xmlSAXHandlerPtr sax,
 void *user_data, int depth, const xmlChar *URL,
 const xmlChar *ID, xmlNodePtr *list) {
    xmlParserCtxtPtr ctxt;
    xmlDocPtr newDoc;
    xmlNodePtr newRoot;
    xmlSAXHandlerPtr oldsax = NULL;
    xmlParserErrors ret = XML_ERR_OK;
    xmlChar start[4];
    xmlCharEncoding enc;

 if (((depth > 40) &&
 ((oldctxt == NULL) || (oldctxt->options & XML_PARSE_HUGE) == 0)) ||
 (depth > 1024)) {
 return(XML_ERR_ENTITY_LOOP);
 }

 if (list != NULL)
 *list = NULL;
 if ((URL == NULL) && (ID == NULL))
 return(XML_ERR_INTERNAL_ERROR);
 if (doc == NULL)
 return(XML_ERR_INTERNAL_ERROR);


    ctxt = xmlCreateEntityParserCtxtInternal(URL, ID, NULL, oldctxt);
 if (ctxt == NULL) return(XML_WAR_UNDECLARED_ENTITY);
    ctxt->userData = ctxt;
 if (oldctxt != NULL) {
	ctxt->_private = oldctxt->_private;
	ctxt->loadsubset = oldctxt->loadsubset;
	ctxt->validate = oldctxt->validate;
	ctxt->external = oldctxt->external;
	ctxt->record_info = oldctxt->record_info;
	ctxt->node_seq.maximum = oldctxt->node_seq.maximum;
	ctxt->node_seq.length = oldctxt->node_seq.length;
	ctxt->node_seq.buffer = oldctxt->node_seq.buffer;
 } else {
 /*
	 * Doing validity checking on chunk without context
	 * doesn't make sense
	 */
	ctxt->_private = NULL;
	ctxt->validate = 0;
	ctxt->external = 2;
	ctxt->loadsubset = 0;
 }
 if (sax != NULL) {
	oldsax = ctxt->sax;
        ctxt->sax = sax;
 if (user_data != NULL)
	    ctxt->userData = user_data;
 }
    xmlDetectSAX2(ctxt);
    newDoc = xmlNewDoc(BAD_CAST "1.0");
 if (newDoc == NULL) {
	ctxt->node_seq.maximum = 0;
	ctxt->node_seq.length = 0;
	ctxt->node_seq.buffer = NULL;
	xmlFreeParserCtxt(ctxt);
 return(XML_ERR_INTERNAL_ERROR);
 }
    newDoc->properties = XML_DOC_INTERNAL;
    newDoc->intSubset = doc->intSubset;
    newDoc->extSubset = doc->extSubset;
    newDoc->dict = doc->dict;
    xmlDictReference(newDoc->dict);

 if (doc->URL != NULL) {
	newDoc->URL = xmlStrdup(doc->URL);
 }
    newRoot = xmlNewDocNode(newDoc, NULL, BAD_CAST "pseudoroot", NULL);
 if (newRoot == NULL) {
 if (sax != NULL)
	    ctxt->sax = oldsax;
	ctxt->node_seq.maximum = 0;
	ctxt->node_seq.length = 0;
	ctxt->node_seq.buffer = NULL;
	xmlFreeParserCtxt(ctxt);
	newDoc->intSubset = NULL;
	newDoc->extSubset = NULL;
        xmlFreeDoc(newDoc);
 return(XML_ERR_INTERNAL_ERROR);
 }
    xmlAddChild((xmlNodePtr) newDoc, newRoot);
    nodePush(ctxt, newDoc->children);
    ctxt->myDoc = doc;
    newRoot->doc = doc;

 /*
     * Get the 4 first bytes and decode the charset
     * if enc != XML_CHAR_ENCODING_NONE
     * plug some encoding conversion routines.
     */
    GROW;
 if ((ctxt->input->end - ctxt->input->cur) >= 4) {
	start[0] = RAW;
	start[1] = NXT(1);
	start[2] = NXT(2);
	start[3] = NXT(3);
	enc = xmlDetectCharEncoding(start, 4);
 if (enc != XML_CHAR_ENCODING_NONE) {
	    xmlSwitchEncoding(ctxt, enc);
 }
 }

 /*
     * Parse a possible text declaration first
     */
 if ((CMP5(CUR_PTR, '<', '?', 'x', 'm', 'l')) && (IS_BLANK_CH(NXT(5)))) {
	xmlParseTextDecl(ctxt);
 }

    ctxt->instate = XML_PARSER_CONTENT;
    ctxt->depth = depth;

    xmlParseContent(ctxt);

 if ((RAW == '<') && (NXT(1) == '/')) {
	xmlFatalErr(ctxt, XML_ERR_NOT_WELL_BALANCED, NULL);
 } else if (RAW != 0) {
	xmlFatalErr(ctxt, XML_ERR_EXTRA_CONTENT, NULL);
 }
 if (ctxt->node != newDoc->children) {
	xmlFatalErr(ctxt, XML_ERR_NOT_WELL_BALANCED, NULL);
 }

 if (!ctxt->wellFormed) {
 if (ctxt->errNo == 0)
	    ret = XML_ERR_INTERNAL_ERROR;
 else
	    ret = (xmlParserErrors)ctxt->errNo;
 } else {
 if (list != NULL) {
	    xmlNodePtr cur;

 /*
	     * Return the newly created nodeset after unlinking it from
	     * they pseudo parent.
	     */
	    cur = newDoc->children->children;
 *list = cur;
 while (cur != NULL) {
		cur->parent = NULL;
		cur = cur->next;
 }
            newDoc->children->children = NULL;
 }
	ret = XML_ERR_OK;
 }

 /*
     * Record in the parent context the number of entities replacement
     * done when parsing that reference.
     */
 if (oldctxt != NULL)
        oldctxt->nbentities += ctxt->nbentities;

 /*
     * Also record the size of the entity parsed
     */
 if (ctxt->input != NULL && oldctxt != NULL) {
	oldctxt->sizeentities += ctxt->input->consumed;
	oldctxt->sizeentities += (ctxt->input->cur - ctxt->input->base);
 }
 /*
     * And record the last error if any
     */
 if (ctxt->lastError.code != XML_ERR_OK)
        xmlCopyError(&ctxt->lastError, &oldctxt->lastError);

 if (sax != NULL)
	ctxt->sax = oldsax;
 if (oldctxt != NULL) {
        oldctxt->node_seq.maximum = ctxt->node_seq.maximum;
        oldctxt->node_seq.length = ctxt->node_seq.length;
        oldctxt->node_seq.buffer = ctxt->node_seq.buffer;
 }
    ctxt->node_seq.maximum = 0;
    ctxt->node_seq.length = 0;
    ctxt->node_seq.buffer = NULL;
    xmlFreeParserCtxt(ctxt);
    newDoc->intSubset = NULL;
    newDoc->extSubset = NULL;
    xmlFreeDoc(newDoc);

 return(ret);
}

xmlParseStringPEReference(xmlParserCtxtPtr ctxt, const xmlChar **str) {
 const xmlChar *ptr;
    xmlChar cur;
    xmlChar *name;
    xmlEntityPtr entity = NULL;

 if ((str == NULL) || (*str == NULL)) return(NULL);
    ptr = *str;
    cur = *ptr;
 if (cur != '%')
 return(NULL);
    ptr++;
    name = xmlParseStringName(ctxt, &ptr);
 if (name == NULL) {
	xmlFatalErrMsg(ctxt, XML_ERR_NAME_REQUIRED,
 "xmlParseStringPEReference: no name\n");
 *str = ptr;
 return(NULL);
 }
    cur = *ptr;
 if (cur != ';') {
	xmlFatalErr(ctxt, XML_ERR_ENTITYREF_SEMICOL_MISSING, NULL);
	xmlFree(name);
 *str = ptr;
 return(NULL);
 }
    ptr++;

 /*
     * Increate the number of entity references parsed
     */
    ctxt->nbentities++;

 /*
     * Request the entity from SAX
     */
 if ((ctxt->sax != NULL) &&
 (ctxt->sax->getParameterEntity != NULL))
	entity = ctxt->sax->getParameterEntity(ctxt->userData, name);
 if (ctxt->instate == XML_PARSER_EOF) {
	xmlFree(name);
 return(NULL);
 }
 if (entity == NULL) {
 /*
	 * [ WFC: Entity Declared ]
	 * In a document without any DTD, a document with only an
	 * internal DTD subset which contains no parameter entity
	 * references, or a document with "standalone='yes'", ...
	 * ... The declaration of a parameter entity must precede
	 * any reference to it...
	 */
 if ((ctxt->standalone == 1) ||
 ((ctxt->hasExternalSubset == 0) && (ctxt->hasPErefs == 0))) {
	    xmlFatalErrMsgStr(ctxt, XML_ERR_UNDECLARED_ENTITY,
 "PEReference: %%%s; not found\n", name);
 } else {
 /*
	     * [ VC: Entity Declared ]
	     * In a document with an external subset or external
	     * parameter entities with "standalone='no'", ...
	     * ... The declaration of a parameter entity must
	     * precede any reference to it...
	     */
	    xmlWarningMsg(ctxt, XML_WAR_UNDECLARED_ENTITY,
 "PEReference: %%%s; not found\n",
			  name, NULL);
	    ctxt->valid = 0;
 }
	xmlParserEntityCheck(ctxt, 0, NULL, 0);
 } else {
 /*
	 * Internal checking in case the entity quest barfed
	 */
 if ((entity->etype != XML_INTERNAL_PARAMETER_ENTITY) &&
 (entity->etype != XML_EXTERNAL_PARAMETER_ENTITY)) {
	    xmlWarningMsg(ctxt, XML_WAR_UNDECLARED_ENTITY,
 "%%%s; is not a parameter entity\n",
			  name, NULL);
 }
 }
    ctxt->hasPErefs = 1;
    xmlFree(name);
 *str = ptr;
 return(entity);
}

xmlParseXMLDecl(xmlParserCtxtPtr ctxt) {
    xmlChar *version;

 /*
     * This value for standalone indicates that the document has an
     * XML declaration but it does not have a standalone attribute.
     * It will be overwritten later if a standalone attribute is found.
     */
    ctxt->input->standalone = -2;

 /*
     * We know that '<?xml' is here.
     */
    SKIP(5);

 if (!IS_BLANK_CH(RAW)) {
	xmlFatalErrMsg(ctxt, XML_ERR_SPACE_REQUIRED,
 "Blank needed after '<?xml'\n");
 }
    SKIP_BLANKS;

 /*
     * We must have the VersionInfo here.
     */
    version = xmlParseVersionInfo(ctxt);
 if (version == NULL) {
	xmlFatalErr(ctxt, XML_ERR_VERSION_MISSING, NULL);
 } else {
 if (!xmlStrEqual(version, (const xmlChar *) XML_DEFAULT_VERSION)) {
 /*
	     * Changed here for XML-1.0 5th edition
	     */
 if (ctxt->options & XML_PARSE_OLD10) {
		xmlFatalErrMsgStr(ctxt, XML_ERR_UNKNOWN_VERSION,
 "Unsupported version '%s'\n",
			          version);
 } else {
 if ((version[0] == '1') && ((version[1] == '.'))) {
		    xmlWarningMsg(ctxt, XML_WAR_UNKNOWN_VERSION,
 "Unsupported version '%s'\n",
				  version, NULL);
 } else {
		    xmlFatalErrMsgStr(ctxt, XML_ERR_UNKNOWN_VERSION,
 "Unsupported version '%s'\n",
				      version);
 }
 }
 }
 if (ctxt->version != NULL)
	    xmlFree((void *) ctxt->version);
	ctxt->version = version;
 }

 /*
     * We may have the encoding declaration
     */
 if (!IS_BLANK_CH(RAW)) {
 if ((RAW == '?') && (NXT(1) == '>')) {
	    SKIP(2);
 return;
 }
	xmlFatalErrMsg(ctxt, XML_ERR_SPACE_REQUIRED, "Blank needed here\n");
 }
    xmlParseEncodingDecl(ctxt);
 if ((ctxt->errNo == XML_ERR_UNSUPPORTED_ENCODING) ||
 (ctxt->instate == XML_PARSER_EOF)) {
 /*
	 * The XML REC instructs us to stop parsing right here
	 */
 return;
 }

 /*
     * We may have the standalone status.
     */
 if ((ctxt->input->encoding != NULL) && (!IS_BLANK_CH(RAW))) {
 if ((RAW == '?') && (NXT(1) == '>')) {
	    SKIP(2);
 return;
 }
	xmlFatalErrMsg(ctxt, XML_ERR_SPACE_REQUIRED, "Blank needed here\n");
 }

 /*
     * We can grow the input buffer freely at that point
     */
    GROW;

    SKIP_BLANKS;
    ctxt->input->standalone = xmlParseSDDecl(ctxt);

    SKIP_BLANKS;
 if ((RAW == '?') && (NXT(1) == '>')) {
        SKIP(2);
 } else if (RAW == '>') {
 /* Deprecated old WD ... */
	xmlFatalErr(ctxt, XML_ERR_XMLDECL_NOT_FINISHED, NULL);
	NEXT;
 } else {
	xmlFatalErr(ctxt, XML_ERR_XMLDECL_NOT_FINISHED, NULL);
	MOVETO_ENDTAG(CUR_PTR);
	NEXT;
 }
}

xmlPopInput(xmlParserCtxtPtr ctxt) {
 if ((ctxt == NULL) || (ctxt->inputNr <= 1)) return(0);
 if (xmlParserDebugEntities)
	xmlGenericError(xmlGenericErrorContext,
 "Popping input %d\n", ctxt->inputNr);
    xmlFreeInputStream(inputPop(ctxt));
 if ((*ctxt->input->cur == 0) &&
 (xmlParserInputGrow(ctxt->input, INPUT_CHUNK) <= 0))
 return(xmlPopInput(ctxt));
 return(CUR);
}

xmlSAXUserParseFile(xmlSAXHandlerPtr sax, void *user_data,
 const char *filename) {
 int ret = 0;
    xmlParserCtxtPtr ctxt;

    ctxt = xmlCreateFileParserCtxt(filename);
 if (ctxt == NULL) return -1;
 if (ctxt->sax != (xmlSAXHandlerPtr) &xmlDefaultSAXHandler)
	xmlFree(ctxt->sax);
    ctxt->sax = sax;
    xmlDetectSAX2(ctxt);

 if (user_data != NULL)
	ctxt->userData = user_data;

    xmlParseDocument(ctxt);

 if (ctxt->wellFormed)
	ret = 0;
 else {
 if (ctxt->errNo != 0)
	    ret = ctxt->errNo;
 else
	    ret = -1;
 }
 if (sax != NULL)
	ctxt->sax = NULL;
 if (ctxt->myDoc != NULL) {
        xmlFreeDoc(ctxt->myDoc);
	ctxt->myDoc = NULL;
 }
    xmlFreeParserCtxt(ctxt);

 return ret;
}

void acquire_object(const sp<ProcessState>& proc,
 const flat_binder_object& obj, const void* who, size_t* outAshmemSize)
{
 switch (obj.type) {
 case BINDER_TYPE_BINDER:
 if (obj.binder) {
                LOG_REFS("Parcel %p acquiring reference on local %p", who, obj.cookie);
 reinterpret_cast<IBinder*>(obj.cookie)->incStrong(who);
 }
 return;
 case BINDER_TYPE_WEAK_BINDER:
 if (obj.binder)
 reinterpret_cast<RefBase::weakref_type*>(obj.binder)->incWeak(who);
 return;
 case BINDER_TYPE_HANDLE: {
 const sp<IBinder> b = proc->getStrongProxyForHandle(obj.handle);
 if (b != NULL) {
                LOG_REFS("Parcel %p acquiring reference on remote %p", who, b.get());
                b->incStrong(who);
 }
 return;
 }
 case BINDER_TYPE_WEAK_HANDLE: {
 const wp<IBinder> b = proc->getWeakProxyForHandle(obj.handle);
 if (b != NULL) b.get_refs()->incWeak(who);
 return;
 }
 case BINDER_TYPE_FD: {
 if ((obj.cookie != 0) && (outAshmemSize != NULL)) {
 struct stat st;
 int ret = fstat(obj.handle, &st);
 if (!ret && S_ISCHR(st.st_mode) && (st.st_rdev == ashmem_rdev())) {
 int size = ashmem_get_size_region(obj.handle);
 if (size > 0) {
 *outAshmemSize += size;
 }
 }
 }
 return;
 }
 }

    ALOGD("Invalid object type 0x%08x", obj.type);
}

